window.CONTENT = {"competencies": ["Comunicação e informação", "Línguas estrangeiras", "Linguagem corporal", "Arte e cultura", "Literatura e seus contextos", "Construção de significados", "Pontos de vista e argumentação", "Língua portuguesa em uso", "Tecnologias e sociedade"], "skills": [{"id": 1, "competency": 1, "label": "Recursos expressivos", "definition": "Identificar as diferentes linguagens e seus recursos expressivos como elementos de caracterização dos sistemas de comunicação.", "explanation": "Observe como palavra, imagem, som, gesto e disposição gráfica constroem sentidos juntos. Não basta listar as linguagens: explique o efeito da combinação.", "example": "Um cartaz mostra uma torneira seca ao lado de “O amanhã depende da gota de hoje”. Como os recursos se articulam?", "answer": "A imagem concretiza a falta de água e a frase associa a economia de hoje ao futuro.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-1"}, {"id": 2, "competency": 1, "label": "Comunicação e problemas sociais", "definition": "Recorrer aos conhecimentos sobre as linguagens dos sistemas de comunicação e informação para resolver problemas sociais.", "explanation": "Use as características de um meio de comunicação para compreender uma solução para um problema coletivo, como acessibilidade ou circulação de informações.", "example": "Uma biblioteca envia por áudio os avisos antes disponíveis apenas em cartazes. Que problema enfrenta?", "answer": "Amplia o acesso à informação para pessoas que não conseguem ler o cartaz.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-13"}, {"id": 3, "competency": 1, "label": "Informação e função social", "definition": "Relacionar informações geradas nos sistemas de comunicação e informação, considerando a função social desses sistemas.", "explanation": "Relacione a informação divulgada à finalidade social do meio: informar, orientar, mobilizar ou permitir a participação pública.", "example": "Um mapa público reúne locais de vacinação e horários. Qual sua função social?", "answer": "Orientar a população para o acesso a um serviço de saúde.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-19"}, {"id": 4, "competency": 1, "label": "Crítica aos meios", "definition": "Reconhecer posições críticas aos usos sociais que são feitos das linguagens e dos sistemas de comunicação e informação.", "explanation": "Identifique a crítica ao modo como a comunicação é usada. Diferencie a voz crítica do texto de uma opinião sua sobre o assunto.", "example": "Uma charge mostra alguém ignorando a pessoa ao lado enquanto comenta “estou superconectado”. Qual é a crítica?", "answer": "A conexão digital pode coexistir com o afastamento nas relações presenciais.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-33"}, {"id": 5, "competency": 2, "label": "Vocabulário em língua estrangeira", "definition": "Associar vocábulos e expressões de um texto em LEM ao seu tema.", "explanation": "Associe palavras e expressões ao tema do texto em inglês ou espanhol. O contexto orienta o sentido, inclusive quando a tradução literal não funciona.", "example": "“Bring your own bottle. Refill here.” Em uma campanha, a que tema remete “refill”?", "answer": "Ao reabastecimento de uma garrafa reutilizável, no contexto de reduzir descartáveis.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-48"}, {"id": 6, "competency": 2, "label": "Acesso a culturas e informações", "definition": "Utilizar os conhecimentos da LEM e de seus mecanismos como meio de ampliar as possibilidades de acesso a informações, tecnologias e culturas.", "explanation": "Leia textos em língua estrangeira para obter informações e compreender práticas culturais. O objetivo é compreender o texto, não traduzir palavra por palavra.", "example": "Um aviso em inglês informa “Free admission on Sundays”. Que informação o visitante obtém?", "answer": "A entrada é gratuita aos domingos.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-70"}, {"id": 7, "competency": 2, "label": "Língua estrangeira em contexto", "definition": "Relacionar um texto em LEM, as estruturas linguísticas, sua função e seu uso social.", "explanation": "Relacione recursos da língua estrangeira à finalidade do gênero e à situação de uso: o que o texto faz e para quem?", "example": "Uma campanha diz “Think before you share”. Qual a função do imperativo?", "answer": "Orientar o leitor a avaliar uma informação antes de compartilhá-la.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-94"}, {"id": 8, "competency": 2, "label": "Diversidade cultural em outras línguas", "definition": "Reconhecer a importância da produção cultural em LEM como representação da diversidade cultural e linguística.", "explanation": "Entenda a produção cultural em outra língua como expressão de identidades e experiências. Evite reduzir culturas a estereótipos.", "example": "Um poema alterna espanhol e inglês para narrar a vida de uma família migrante. O que essa alternância pode expressar?", "answer": "Uma identidade formada pela convivência de línguas e culturas.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-111"}, {"id": 9, "competency": 3, "label": "Movimento e cultura", "definition": "Reconhecer as manifestações corporais de movimento como originárias de necessidades cotidianas de um grupo social.", "explanation": "Reconheça que danças, jogos e outras práticas corporais respondem a necessidades e histórias de grupos sociais.", "example": "Uma dança comunitária representa movimentos do trabalho agrícola. Qual relação aparece?", "answer": "A prática corporal reelabora atividades e experiências cotidianas do grupo.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-128"}, {"id": 10, "competency": 3, "label": "Hábitos corporais", "definition": "Reconhecer a necessidade de transformação de hábitos corporais em função das necessidades cinestésicas.", "explanation": "Analise por que uma prática corporal precisa mudar diante das necessidades do corpo. Considere saúde, rotina e condições concretas.", "example": "Um programa oferece pausas de movimento a quem passa horas sentado. Por que adaptar a rotina?", "answer": "Para responder às necessidades corporais associadas a uma rotina sedentária.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-143"}, {"id": 11, "competency": 3, "label": "Corpo e inclusão", "definition": "Reconhecer a linguagem corporal como meio de interação social, considerando os limites de desempenho e as alternativas de adaptação para diferentes indivíduos.", "explanation": "Identifique adaptações que permitem participação e interação. Inclusão não exige que todos tenham o mesmo desempenho.", "example": "Um jogo usa bola sonora e sinalizações táteis. Qual o sentido dessas adaptações?", "answer": "Ampliar as possibilidades de participação de pessoas com deficiência visual.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-150"}, {"id": 12, "competency": 4, "label": "Funções da arte", "definition": "Reconhecer diferentes funções da arte, do trabalho da produção dos artistas em seus meios culturais.", "explanation": "Relacione a obra à função que assume no seu contexto: expressar, denunciar, preservar memória, celebrar ou provocar reflexão.", "example": "Um mural retrata moradores e suas histórias em uma praça. Que função pode assumir?", "answer": "Dar visibilidade às experiências e à memória daquela comunidade.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-165"}, {"id": 13, "competency": 4, "label": "Arte, beleza e preconceito", "definition": "Analisar as diversas produções artísticas como meio de explicar diferentes culturas, padrões de beleza e preconceitos.", "explanation": "Observe como uma produção artística questiona ou reproduz padrões de beleza, hierarquias culturais e preconceitos.", "example": "Uma exposição usa retratos de corpos diversos para questionar imagens publicitárias. O que problematiza?", "answer": "A imposição de um padrão restrito de beleza e os preconceitos associados a ele.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-182"}, {"id": 14, "competency": 4, "label": "Diversidade artística", "definition": "Reconhecer o valor da diversidade artística e das inter-relações de elementos que se apresentam nas manifestações de vários grupos sociais e étnicos.", "explanation": "Reconheça encontros entre tradições artísticas e o valor das manifestações de diferentes grupos, sem hierarquizar culturas.", "example": "Um espetáculo reúne canto de tradição indígena e instrumentos eletrônicos sem apagar sua origem. Que relação valoriza?", "answer": "O diálogo entre manifestações culturais, reconhecendo suas particularidades.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-192"}, {"id": 15, "competency": 5, "label": "Literatura e história", "definition": "Estabelecer relações entre o texto literário e o momento de sua produção, situando aspectos do contexto histórico, social e político.", "explanation": "Relacione marcas do texto literário às condições históricas, sociais ou políticas de sua produção. A data sozinha não resolve a interpretação.", "example": "Um romance retrata expulsões de famílias para modernizar uma cidade. Como situar esse conflito?", "answer": "Relacionando os acontecimentos da obra às disputas sociais do contexto representado.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-203"}, {"id": 16, "competency": 5, "label": "Construção do texto literário", "definition": "Relacionar informações sobre concepções artísticas e procedimentos de construção do texto literário.", "explanation": "Analise como a obra é construída: imagens, ritmo, voz, estrutura, experimentação e procedimentos de determinada concepção artística.", "example": "Um poema dispensa rima regular e usa linguagem cotidiana. Que análise cabe?", "answer": "Explicar como as escolhas de forma e linguagem participam da concepção artística do poema.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-215"}, {"id": 17, "competency": 5, "label": "Valores na literatura", "definition": "Reconhecer a presença de valores sociais e humanos atualizáveis e permanentes no patrimônio literário nacional.", "explanation": "Identifique conflitos e valores humanos que permanecem relevantes: injustiça, solidariedade, identidade, memória e relações de poder.", "example": "Uma narrativa antiga retrata alguém excluído por sua origem. Por que o conflito permanece atual?", "answer": "Porque permite discutir discriminações e relações de poder ainda presentes.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-234"}, {"id": 18, "competency": 6, "label": "Organização e progressão", "definition": "Identificar os elementos que concorrem para a progressão temática e para a organização e estruturação de textos de diferentes gêneros e tipos.", "explanation": "Acompanhe como o texto avança: retomadas, conectivos, sequência de ideias e organização do gênero. Pergunte o que cada parte acrescenta.", "example": "Uma crônica passa de uma lembrança pessoal a uma conclusão geral. Como progride?", "answer": "O caso particular serve de ponto de partida para uma reflexão mais ampla.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-254"}, {"id": 19, "competency": 6, "label": "Funções da linguagem", "definition": "Analisar a função da linguagem predominante nos textos em situações específicas de interlocução.", "explanation": "Identifique o foco da comunicação naquela situação. Uma função pode predominar mesmo quando outras aparecem.", "example": "Um dicionário define o significado de “crônica”. Que função predomina?", "answer": "A metalinguística: usa a linguagem para explicar um elemento da própria linguagem.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-274"}, {"id": 20, "competency": 6, "label": "Memória linguística", "definition": "Reconhecer a importância do patrimônio linguístico para a preservação da memória e da identidade nacional.", "explanation": "Reconheça como palavras, relatos e tradições de linguagem preservam experiências, memória e identidade coletiva.", "example": "Uma comunidade registra em áudio histórias e palavras de seus mais velhos. Que patrimônio preserva?", "answer": "A memória coletiva e os usos da língua ligados à identidade do grupo.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-283"}, {"id": 21, "competency": 7, "label": "Persuasão verbal e visual", "definition": "Reconhecer em textos de diferentes gêneros, recursos verbais e não-verbais utilizados com a finalidade de criar e mudar comportamentos e hábitos.", "explanation": "Analise a combinação entre palavras e elementos visuais que procura provocar uma atitude ou mudar um hábito.", "example": "Uma campanha combina fotografia de uma ciclovia ocupada por carros e o pedido “Deixe o caminho livre”. Que efeito busca?", "answer": "Mobilizar o leitor a mudar sua conduta para respeitar o espaço dos ciclistas.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-292"}, {"id": 22, "competency": 7, "label": "Comparação de textos", "definition": "Relacionar, em diferentes textos, opiniões, temas, assuntos e recursos linguísticos.", "explanation": "Compare textos pelo que afirmam e pela forma como tratam o tema. Compartilhar o assunto não significa defender a mesma posição.", "example": "Um texto afirma que telas eliminaram os bilhetes; outro mostra bilhetes ao lado de celulares. Como se relacionam?", "answer": "Divergem: o primeiro defende substituição; o segundo evidencia coexistência.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-301"}, {"id": 23, "competency": 7, "label": "Intenção e público", "definition": "Inferir em um texto quais são os objetivos de seu produtor e quem é seu público alvo, pela análise dos procedimentos argumentativos utilizados.", "explanation": "Infira a intenção e o público pelas escolhas do texto: vocabulário, exemplos, argumentos, suporte e forma de abordar o leitor.", "example": "Um anúncio começa com “Você que se prepara para o vestibular...” e destaca simulados. A quem se dirige?", "answer": "A estudantes interessados na preparação para exames, inferidos pelo tratamento e pela oferta.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-313"}, {"id": 24, "competency": 7, "label": "Estratégias argumentativas", "definition": "Reconhecer no texto estratégias argumentativas empregadas para o convencimento do público, tais como a intimidação, sedução, comoção, chantagem, entre outras.", "explanation": "Reconheça o caminho escolhido para convencer: autoridade, dados, exemplos, apelo afetivo, ameaça ou promessa. Avalie a função desse recurso no texto.", "example": "Uma campanha cita uma pesquisadora para sustentar uma recomendação. Qual estratégia utiliza?", "answer": "O argumento de autoridade, atribuindo credibilidade a uma fonte reconhecida.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-326"}, {"id": 25, "competency": 8, "label": "Marcas da variação", "definition": "Identificar, em textos de diferentes gêneros, as marcas linguísticas que singularizam as variedades linguísticas sociais, regionais e de registro.", "explanation": "Identifique marcas de variedades regionais, sociais e de registro sem tratá-las automaticamente como erros.", "example": "Um personagem diz “Oxente, tu chegou cedo!”. Que análise é pertinente?", "answer": "As escolhas de vocabulário e construção marcam uma variedade de língua, sem indicar incapacidade do falante.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-343"}, {"id": 26, "competency": 8, "label": "Variação em contexto", "definition": "Relacionar as variedades linguísticas a situações específicas de uso social.", "explanation": "Relacione a variedade linguística à situação de comunicação e à relação entre interlocutores. Adequação depende do contexto.", "example": "Uma mensagem entre amigos diz “bora marcar?”; um pedido à direção diz “Solicito uma reunião”. Por que diferem?", "answer": "Pela adequação do registro à relação entre interlocutores e à situação.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-352"}, {"id": 27, "competency": 8, "label": "Norma padrão em uso", "definition": "Reconhecer os usos da norma padrão da língua portuguesa nas diferentes situações de comunicação.", "explanation": "Analise o uso da norma padrão e sua adequação a diferentes situações. Um desvio pode também construir um efeito expressivo deliberado.", "example": "Uma escritora usa “me dá” em diálogo e “dá-me” para imitar um documento solene. Qual o efeito?", "answer": "O contraste de registros contribui para caracterizar as situações e as vozes.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-359"}, {"id": 28, "competency": 9, "label": "Impacto das tecnologias", "definition": "Reconhecer a função e o impacto social das diferentes tecnologias da comunicação e informação.", "explanation": "Compreenda como um meio altera relações, hábitos e acesso a informações, observando também desigualdades e efeitos sociais.", "example": "Uma crônica mostra bilhetes de papel convivendo com mensagens digitais. Que impacto discute?", "answer": "A reorganização dos usos da escrita, sem eliminação necessária das tecnologias anteriores.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-368"}, {"id": 29, "competency": 9, "label": "Linguagens das tecnologias", "definition": "Identificar pela análise de suas linguagens, as tecnologias da comunicação e informação.", "explanation": "Reconheça características de linguagem que distinguem tecnologias, como links, hipertexto, interação e combinação de mídias.", "example": "Ao tocar uma palavra, o leitor abre outro documento e retorna ao trecho anterior. Que recurso caracteriza a leitura?", "answer": "A navegação por hiperlinks, que conecta percursos de informação.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-382"}, {"id": 30, "competency": 9, "label": "Tecnologia e sociedade", "definition": "Relacionar as tecnologias de comunicação e informação ao desenvolvimento das sociedades e ao conhecimento que elas produzem.", "explanation": "Relacione mudanças tecnológicas às formas de produzir, compartilhar e organizar conhecimento na sociedade.", "example": "Um arquivo digital permite consultar documentos antes acessíveis apenas numa instituição distante. O que muda?", "answer": "As condições de circulação e consulta do conhecimento, embora o acesso dependa de conectividade.", "source": "Exemplo breve autoral para demonstrar a operação de leitura.", "examExampleId": "enem-ppl-399"}], "subjects": [{"id": 1, "title": "Tipos textuais", "skills": [18, 23], "body": "Não confunda o modo de organizar o texto com seu gênero. Narração encadeia acontecimentos; descrição apresenta características; exposição explica; argumentação sustenta uma posição; injunção orienta uma ação. Um gênero pode combinar diferentes tipos. A pergunta do ENEM costuma exigir reconhecer a organização dominante e seu papel no contexto.", "quote": "Às oito, Clara abriu a janela. A rua estava vazia. Ela guardou o bilhete no bolso e saiu.", "stem": "A sequência se organiza predominantemente pela", "options": ["defesa de uma tese sobre a vida na cidade.", "orientação de etapas a serem seguidas.", "explicação de um fenômeno social.", "sucessão de ações de uma personagem.", "comparação de opiniões sobre um bilhete."], "key": 3, "comment": "Os verbos abriu, guardou e saiu encadeiam ações. “A rua estava vazia” insere uma descrição, mas não altera o predomínio narrativo.", "source": "Questão autoral de demonstração. Modelagem baseada nos materiais enviados; não é um item oficial do ENEM.", "examExampleId": "tipos-2018-cores"}, {"id": 2, "title": "Gêneros textuais", "skills": [18, 23], "body": "O gênero se define por uma prática social: quem escreve, para quem, com qual finalidade e em qual situação. Crônica, notícia, bilhete e artigo de opinião não são apenas formatos. Uma crônica pode partir de uma cena cotidiana e transformá-la em reflexão; uma notícia organiza informações sobre um acontecimento.", "quote": "Na geladeira: “Ana, deixei a sopa na panela. Volto às sete. Beijo, mãe.”", "stem": "A caracterização desse texto como bilhete decorre da", "options": ["comunicação breve situada numa relação cotidiana.", "apresentação impessoal de um acontecimento público.", "demonstração de uma tese por dados verificáveis.", "explicação sistemática de um conceito científico.", "representação detalhada de uma cena ficcional."], "key": 0, "comment": "O texto atende a uma necessidade de comunicação familiar. O local e os interlocutores ajudam a identificar sua função; ser curto, sozinho, não define um gênero.", "source": "Questão autoral de demonstração. Modelagem baseada nos materiais enviados; não é um item oficial do ENEM.", "examExampleId": "enem-ppl-1"}, {"id": 3, "title": "Língua em uso", "skills": [25, 26, 27], "body": "Variedades linguísticas expressam comunidades, situações e relações entre falantes. Registro formal ou informal depende da interação. Norma padrão é uma referência usada em determinadas práticas; não esgota a língua. Avalie a adequação ao contexto e os efeitos de sentido, evitando preconceito linguístico.", "quote": "Para o colega: “Bora combinar o trabalho?”. Para a direção: “Solicito uma reunião para organizar o trabalho.”", "stem": "A mudança de registro se relaciona à", "options": ["superioridade intelectual de quem usa a forma solene.", "impossibilidade de falar informalmente sobre estudos.", "adequação da linguagem à relação com o interlocutor.", "substituição definitiva da fala espontânea pela escrita.", "ausência de regras em situações entre estudantes."], "key": 2, "comment": "A relação com o destinatário orienta o registro. As duas mensagens são compreensíveis e adequadas a situações distintas.", "source": "Questão autoral de demonstração. Modelagem baseada nos materiais enviados; não é um item oficial do ENEM.", "examExampleId": "enem-ppl-359"}, {"id": 4, "title": "Funções da linguagem", "skills": [19], "body": "Observe o foco do ato comunicativo: referente (referencial), emissor (emotiva), destinatário (conativa), canal (fática), código (metalinguística) ou elaboração da mensagem (poética). Funções convivem; reconhecer uma palavra isolada não basta para identificar a predominante.", "quote": "“Crônica: narrativa breve que frequentemente aborda situações do cotidiano.”", "stem": "A função predominante nessa definição é a", "options": ["fática, por verificar o contato entre interlocutores.", "metalinguística, por explicar um elemento da linguagem.", "emotiva, por expressar um estado pessoal do autor.", "conativa, por ordenar uma mudança de comportamento.", "poética, por explorar a sonoridade das palavras."], "key": 1, "comment": "A linguagem explica o sentido de um termo usado para nomear um gênero. Essa operação caracteriza a função metalinguística.", "source": "Questão autoral de demonstração. Modelagem baseada nos materiais enviados; não é um item oficial do ENEM.", "examExampleId": "enem-ppl-274"}, {"id": 5, "title": "Publicidade e textos multimodais", "skills": [1, 21, 24], "body": "Em anúncios, campanhas, charges e infográficos, leia palavras, imagens, cores e organização como partes de uma construção de sentido. Não suponha que a imagem apenas ilustra o texto. Pergunte como esses recursos orientam a interpretação e que comportamento procuram produzir.", "quote": "Um cartaz apresenta a imagem de uma torneira seca e a frase: “O amanhã depende da gota de hoje”.", "stem": "A articulação dos recursos busca", "options": ["anunciar que a água já acabou em todas as cidades.", "substituir a imagem por uma instrução de manutenção.", "atribuir a seca exclusivamente a um evento natural.", "apresentar um relatório sobre consumo industrial.", "associar a economia de água à preservação futura."], "key": 4, "comment": "A torneira seca concretiza o risco; a frase liga a ação presente ao futuro. A campanha pretende mobilizar uma mudança de hábito.", "source": "Questão autoral de demonstração. Modelagem baseada nos materiais enviados; não é um item oficial do ENEM.", "examExampleId": "enem-ppl-292"}, {"id": 6, "title": "Estratégias argumentativas", "skills": [23, 24], "body": "Encontre a tese e analise como o texto tenta torná-la aceitável. Dados, exemplos, comparação, autoridade e apelos afetivos cumprem funções diferentes. Citar uma fonte não torna automaticamente uma conclusão válida: observe a relação entre evidência e argumento.", "quote": "“Devemos reduzir o desperdício. Segundo a pesquisadora responsável pelo estudo, separar as sobras ajuda a identificar onde ocorre a maior perda.”", "stem": "A referência à pesquisadora funciona como", "options": ["ameaça de punição a quem mantém o hábito.", "apelo à popularidade de uma prática cotidiana.", "recurso de autoridade para sustentar a orientação.", "relato pessoal que dispensa uma justificativa.", "comparação entre situações historicamente opostas."], "key": 2, "comment": "A fala atribuída à especialista oferece credibilidade à recomendação. A validade da orientação ainda depende da evidência e de seu contexto.", "source": "Questão autoral de demonstração. Modelagem baseada nos materiais enviados; não é um item oficial do ENEM.", "examExampleId": "enem-ppl-326"}, {"id": 7, "title": "Comparação e intertextualidade", "skills": [22], "body": "Comparar exige estabelecer uma relação: convergência, divergência, complemento ou diferença de perspectiva. Intertextualidade envolve retomada de outro texto, que pode ocorrer por citação, alusão, paródia ou transformação. Um tema comum sozinho não demonstra intertextualidade.", "quote": "Texto I: “As mensagens digitais tornaram inúteis os bilhetes de papel.” Texto II: “Uso o celular todos os dias e ainda deixo recados na geladeira.”", "stem": "As perspectivas se diferenciam porque o texto II", "options": ["apresenta coexistência onde o texto I afirma substituição.", "confirma que os bilhetes perderam sua função cotidiana.", "nega a presença de tecnologias digitais na rotina.", "atribui a ambos os meios a mesma origem histórica.", "defende o uso exclusivo de papel na comunicação."], "key": 0, "comment": "A conjunção “e ainda” combina práticas. O texto I pressupõe eliminação; o II traz um caso de convivência.", "source": "Questão autoral de demonstração. Modelagem baseada nos materiais enviados; não é um item oficial do ENEM.", "examExampleId": "enem-ppl-301"}, {"id": 8, "title": "Literatura e vanguardas", "skills": [12, 13, 14, 15, 16, 17], "body": "Relacione forma, visão de mundo e contexto. Vanguardas artísticas experimentaram modos de representar e questionaram convenções, com projetos distintos. Nas questões, nomes de escolas ajudam, mas a interpretação precisa mostrar como a obra constrói sentidos. Literatura não se reduz a um retrato direto da realidade.", "quote": "Poema autoral: “Na rua / o anúncio grita / eu, ponto pequeno / atravesso”.", "stem": "O contraste entre o anúncio e o eu lírico sugere", "options": ["a ausência de comunicação no espaço urbano.", "a valorização da publicidade como voz íntima.", "a descrição neutra das dimensões de uma placa.", "o apagamento do indivíduo diante de mensagens urbanas.", "a defesa explícita de uma escola artística específica."], "key": 3, "comment": "“Grita” personifica o anúncio; “ponto pequeno” reduz o eu lírico. O contraste produz uma experiência de desproporção. O trecho não permite atribuir com segurança uma escola específica.", "source": "Questão autoral de demonstração. Modelagem baseada nos materiais enviados; não é um item oficial do ENEM.", "examExampleId": "enem-ppl-182"}, {"id": 9, "title": "Leitura e interpretação de poemas", "skills": [16, 17], "body": "Leia o poema como construção: imagens, ritmo, pausas, repetição, voz e relação entre versos. Eu lírico não se confunde automaticamente com a pessoa do autor. Uma metáfora aproxima campos de sentido; explique o efeito que produz no conjunto, sem transformar toda imagem em mensagem literal.", "quote": "Poema autoral: “Guardo a tarde / num bolso de silêncio. / Quando te lembro, / a luz transborda.”", "stem": "A expressão “a luz transborda” constrói", "options": ["um relato técnico sobre a intensidade de uma lâmpada.", "a imagem da lembrança como experiência que excede limites.", "uma instrução para preservar um objeto luminoso.", "a comprovação de que a tarde cabe fisicamente no bolso.", "a negação de qualquer vínculo entre memória e emoção."], "key": 1, "comment": "A lembrança é figurada como luz que não cabe no limite sugerido pelo bolso. A leitura conecta as imagens em vez de interpretar cada palavra literalmente.", "source": "Questão autoral de demonstração. Modelagem baseada nos materiais enviados; não é um item oficial do ENEM.", "examExampleId": "enem-ppl-215"}], "activities": [{"id": "enem-2025-punho", "title": "O punho e o pixel", "subtitle": "Uma crônica. Cinco caminhos de leitura.", "author": "Ana Elisa Ribeiro", "source": "ENEM 2025 • 1º dia • Caderno 3 (branco), pp. 6–7. Texto “De próprio punho”, adaptado de Rascunho no exame.", "kind": "Treino comentado", "paragraphs": ["Estranhei muito na primeira vez que escutei a expressão “de próprio punho”. Parecia que eu ia bater em alguém. Não era bem o caso. Foi numa situação bancária, dessas bem burocráticas, e eu devia escrever algo bem breve, mas com minhas mãos. Na verdade, o que importava era a autenticidade da minha caligrafia, que à época ainda era mais fluente e firme. Depois dos teclados de computador, ela rateia bastante. Minha letra, hoje, tem uma espécie de alternância: dia sim, dia não, trêmula e firme, forte e fraca, mais rotunda e mais cheia de arestas.", "É claro que já escrevi muito mais de próprio punho ou, numa palavra mais bonita, manuscrevi (prefiro a mão ao punho, embora ele também seja usado na tarefa). Mas isso não é um feito individual. Em larga medida, é social. Muita gente sente o mesmo que eu, isto é, escreve bem menos usando as mãos, ou melhor, empregando algum tipo de tecnologia (lápis, caneta etc.) para escrever com grafite ou tinta ou giz ou carvão ou sangue e o que mais. É importante lembrar que ainda há gente que não sabe escrever neste país, neste planeta, mas muita gente sabe e tem um combo de tecnologias mais ou menos à disposição para isso. Sou dessas pessoas privilegiadas que têm várias possibilidades, e uma delas nunca deixou de ser o uso das minhas mãos. Ainda hoje, são elas que batucam meu teclado de computador ou que tocam suavemente duas ou três telas sensíveis. Mas não expressam mais a minha letra. No lugar, aparecem Times New Roman, Arial, Calibri e mais uma centena de “letras” à minha escolha. Eu e Deus e o mundo.", "A despeito desse rol de chances e ferramentas para escrever, o manuscrito nunca deixou de pintar aqui e ali, muitas vezes como obrigação. Na escola, por exemplo, até hoje ele é soberano. No Enem também. Curioso, não? Fico pensando em que espaços e ocasiões ainda uso minha letra. Olhando ao redor, na minha casa, minha letra está em espaços muito delimitados e específicos: bilhetes. Eles estão principalmente na cozinha, em especial na porta da geladeira, a fim de manter a comunicação com meus coabitantes, sempre muito esquecidos ou relapsos. Mas também há bilhetes em post its na minha mesa do escritório, textinhos em garranchos por meio dos quais me comunico comigo mesma, a evitar um comportamento esquecido e relapso.", "No escritório, costumo ser mais suave comigo mesma, mas também muito mais lacônica, a ponto de nem eu me entender, se passar o tempo. Em todos os casos vai minha letra, menos e mais redonda, a lápis e a tinta azul, em post its rosa-choque, colados precariamente, e todos com destino à lixeira, em breve. Justo porque eles funcionam como lembretes de tarefas e coisas que devem ser vencidas e, claro, substituídas por outras, num fluxo infinito, às vezes ansiogênico, com que a maioria dos adultos (e mais ainda as adultas) precisa conviver.", "As formas de escrever mudam, as necessidades também, e o resultado é um elenco complexo, em que nada dispensa nada, a depender da tarefa ou da importância das coisas ou de suas funções, claro. A escrita e suas tecnologias incríveis vão se reposicionando, mudando de status, numa ciranda interessante e importante que pode ser vista à luz de certa diversidade que encontra suas oportunidades e seus efeitos, aqui e ali. Não adianta muito pensar sempre como se tudo fosse excludente. Estão aí minha farta comunicação por bilhetes, minha gaveta alegre de post its de toda cor, esperando para serem usados, e o cheque do cartório, em que quase tudo já é digital. “Do punho ao pixel” não é uma frase filosoficamente correta. O negócio é mais “o punho e o pixel”."], "questions": [{"id": "q6", "number": 6, "stem": "O elemento que caracteriza esse texto como uma crônica é a", "options": ["defesa das opiniões da autora sobre um tema de interesse coletivo.", "exposição sobre o uso de tecnologias nas práticas de escrita atuais.", "abordagem de fatos do contexto pessoal em uma perspectiva reflexiva.", "utilização de recursos linguísticos para a interlocução direta com o leitor.", "apresentação de acontecimentos segundo a ordem de sucessão no tempo."], "key": 2, "skill": 23, "ref": 1, "comment": "A experiência pessoal, iniciada por “Estranhei muito”, conduz à reflexão sobre práticas de escrita. Esse movimento do cotidiano para uma reflexão caracteriza a crônica.", "distractors": ["Defender opiniões ocorre em vários gêneros e não caracteriza sozinho a crônica.", "O tema tecnológico não determina o gênero.", "Correta: o caso pessoal sustenta uma perspectiva reflexiva.", "Interlocução com o leitor também aparece em outros gêneros.", "A sequência temporal não é a característica central dessa crônica."], "difficulty": "medium"}, {"id": "q7", "number": 7, "stem": "No que diz respeito ao gênero bilhete, a autora dessa crônica", "options": ["ressalta a formalidade na comunicação com as pessoas de sua convivência.", "critica a ansiedade causada pela velocidade da comunicação.", "expressa a obrigatoriedade de concisão nas anotações.", "questiona a prática da escrita de próprio punho.", "apresenta a diversidade de usos no cotidiano."], "key": 4, "skill": 23, "ref": 3, "comment": "Os bilhetes servem tanto à comunicação com coabitantes quanto a lembretes dirigidos à própria autora. A diversidade de funções aparece nos parágrafos 3 e 4.", "distractors": ["Os exemplos são cotidianos e não ressaltam formalidade.", "A ansiedade se relaciona ao fluxo de tarefas, não define sua análise do gênero.", "A autora relata concisão pessoal, sem transformá-la em obrigação do gênero.", "Ela reconhece o uso da escrita manual, sem condená-lo.", "Correta: recados a outras pessoas e lembretes a si mesma mostram diferentes usos."], "difficulty": "easy"}, {"id": "q8", "number": 8, "stem": "O recurso linguístico usado para marcar a síntese da opinião da autora sobre a temática desenvolvida foi o(a)", "options": ["emprego da primeira pessoa em “Estranhei muito na primeira vez que escutei a expressão ‘de próprio punho’”.", "utilização de locução adverbial em “Na verdade, o que importava era a autenticidade da minha caligrafia”.", "uso de pronome possessivo em “Minha letra, hoje, tem uma espécie de alternância”.", "adoção de termo autorreflexivo em “No escritório, costumo ser mais suave comigo mesma”.", "substituição da expressão “Do punho ao pixel” pela expressão “o punho e o pixel”."], "key": 4, "skill": 18, "ref": 5, "comment": "A troca de “ao” por “e” concentra a posição da autora: a escrita digital e a manual coexistem. A formulação do último parágrafo sintetiza o percurso argumentativo.", "distractors": ["A primeira pessoa introduz uma experiência, não sintetiza a tese.", "A locução esclarece o episódio no banco.", "O possessivo caracteriza a caligrafia da autora.", "O termo aponta a relação da autora consigo, não a conclusão geral.", "Correta: “e” expressa coexistência, em lugar de uma passagem que sugere substituição."], "difficulty": "hard"}, {"id": "q9", "number": 9, "stem": "Nesse texto, o que caracteriza a escrita “de próprio punho” é a letra manuscrita, enquanto a escrita digital é ilustrada pelo(a)", "options": ["utilização de tecnologias diversificadas.", "desenvolvimento de novos recursos de escrita.", "possibilidade de interações mediadas por telas.", "diversidade de fontes tipográficas que estão disponíveis.", "delimitação dos espaços onde a produção textual ocorre."], "key": 3, "skill": 29, "ref": 2, "comment": "Times New Roman, Arial e Calibri exemplificam as fontes digitais, em contraste com os traços próprios da caligrafia. O dado específico aparece no segundo parágrafo.", "distractors": ["A variedade de tecnologias também inclui lápis e caneta.", "É uma afirmação ampla que não corresponde ao exemplo específico.", "O toque em telas aparece, mas o contraste da letra se concretiza nas fontes.", "Correta: as fontes são nomeadas como as “letras” à escolha.", "Os espaços delimitados dizem respeito sobretudo aos bilhetes manuscritos."], "difficulty": "easy"}, {"id": "q10", "number": 10, "stem": "A autora conclui que as novas tecnologias de escrita", "options": ["evoluem para facilitar a vida cotidiana.", "alcançam diferentes realidades sociais.", "coexistem com outras já estabelecidas.", "promovem maior agilidade na comunicação.", "surgem nos contextos em que são necessárias."], "key": 2, "skill": 28, "ref": 5, "comment": "“Nada dispensa nada” e “o punho e o pixel” sustentam a convivência de tecnologias, cujo uso se reorganiza conforme tarefas e funções.", "distractors": ["Facilitação não é a tese central da conclusão.", "O texto menciona desigualdade, mas não conclui pela universalização.", "Correta: manuscrito e digital convivem e mudam de função.", "A rapidez não sintetiza a conclusão apresentada.", "O texto trata da reorganização de usos, não da origem das tecnologias."], "difficulty": "medium"}], "note": "Itens transcritos do PDF enviado. Na questão 08, as referências de linhas foram convertidas em parágrafos para facilitar a leitura no celular. Comentários e associação a habilidades são análise pedagógica do app."}, {"id": "a-noticia-no-bolso", "title": "A notícia que cabe no bolso", "subtitle": "Compartilhar é rápido. Compreender exige outra pausa.", "author": "Equipe Entrelinhas · texto autoral", "source": "Texto e questões autorais de demonstração. Estrutura inspirada nos blocos de leitura enviados pelo professor.", "kind": "Leitura da edição", "note": "Questões autorais para revisão pedagógica do professor. Treino local, sem pontuação no ranking.", "paragraphs": ["No intervalo, o telefone de Júlia vibrou com uma manchete: “Pesquisa prova que estudantes aprendem menos com telas”. Ela enviou o link ao grupo antes de abrir a reportagem. Quando alguém perguntou quais estudantes haviam participado do estudo, voltou à página. A notícia parecia ter chegado inteira; o conhecimento, não.", "A reportagem descrevia uma pesquisa feita com adultos universitários, em uma tarefa curta de leitura, sob condições controladas. Os resultados comparavam o desempenho em dois suportes naquele recorte. Não tratavam de todas as idades, de todas as atividades nem de todos os modos de usar uma tela. A manchete não inventara o tema, mas apagara os limites que permitiam compreendê-lo.", "A economia de palavras ajuda a atrair atenção. Torna-se um problema quando transforma um resultado situado em uma sentença geral. “Nesse experimento, em certa tarefa” ocupa mais espaço do que “a ciência prova”. E pede do leitor uma coisa pouco compatível com a pressa do intervalo: aceitar que uma resposta pode precisar de condições.", "Júlia não abandonou o telefone. Também não decidiu acreditar apenas em notícias longas. Abriu o estudo indicado na reportagem, verificou quem o havia produzido e enviou uma segunda mensagem ao grupo: “Compartilhei antes de ler. O resultado é mais específico do que o título sugere”. A correção recebeu menos reações do que a primeira postagem.", "Talvez a diferença entre estar informado e apenas receber informação comece aí: não na escolha entre papel e tela, mas na disposição de interrogar o que chega. Um link cabe no bolso. As perguntas que ele exige nem sempre cabem na manchete."], "questions": [{"id": "autoral-1", "stem": "A relação entre a manchete e a pesquisa é marcada pela", "options": ["apresentação de uma conclusão mais ampla do que os dados descritos autorizam.", "invenção de um tema sem correspondência com o estudo mencionado.", "defesa de um resultado contrário ao obtido na comparação entre suportes.", "substituição dos participantes por estudantes de outras faixas etárias.", "negação de qualquer diferença observável entre os suportes investigados."], "key": 0, "skill": 22, "ref": 2, "comment": "O título generaliza para estudantes e telas um resultado situado numa tarefa com universitários. O texto distingue exagero de alcance e invenção do tema.", "distractors": ["Correta: os limites do estudo foram apagados na manchete.", "O parágrafo 2 afirma que a manchete não inventou o tema.", "Não se afirma que o título inverteu o resultado observado.", "A comparação é de alcance da afirmação, não de substituição real da amostra.", "O texto não nega diferenças; delimita em que condições foram medidas."], "difficulty": "medium"}, {"id": "autoral-2", "stem": "No percurso de Júlia, a segunda mensagem ao grupo cumpre a função de", "options": ["rejeitar o uso de aparelhos digitais para a leitura de notícias.", "confirmar que o título dispensava a consulta à reportagem.", "reparar uma divulgação feita sem examinar seus limites.", "transferir aos colegas a responsabilidade pela primeira postagem.", "atribuir às reações do grupo a validade do resultado científico."], "key": 2, "skill": 23, "ref": 4, "comment": "Ao admitir que compartilhou antes de ler e explicar o alcance específico da pesquisa, Júlia corrige sua divulgação. A mudança é de conduta, não de suporte.", "distractors": ["Ela continua usando o telefone.", "A segunda mensagem aponta justamente o limite do título.", "Correta: reconhecimento do erro e contextualização repararam a postagem.", "Ela assume a própria decisão, sem culpar o grupo.", "O número de reações não valida uma pesquisa."], "difficulty": "easy"}, {"id": "autoral-3", "stem": "A oposição entre “a notícia” e “o conhecimento”, no primeiro parágrafo, distingue", "options": ["a superioridade do impresso sobre qualquer leitura digital.", "a informação científica de uma experiência exclusivamente pessoal.", "a confiança no jornalismo da desconfiança na pesquisa acadêmica.", "a leitura de notícias longas da leitura de notícias sem autoria.", "a chegada de um conteúdo da compreensão de suas condições."], "key": 4, "skill": 18, "ref": 1, "comment": "O link circula antes de Júlia conhecer participantes e condições do estudo. O contraste estabelece o tema que será desenvolvido: receber informação não equivale a compreendê-la.", "distractors": ["A conclusão rejeita escolher entre papel e tela como solução.", "A oposição não se organiza entre ciência e experiência pessoal.", "O texto recomenda examinar fontes e evidências.", "Comprimento e autoria não constituem a oposição indicada.", "Correta: circulação do conteúdo e compreensão são processos distintos."], "difficulty": "medium"}, {"id": "autoral-4", "stem": "No terceiro parágrafo, a comparação entre as duas formulações evidencia a", "options": ["necessidade de abandonar a concisão em toda prática jornalística.", "tensão entre o apelo de uma certeza breve e o rigor de uma conclusão situada.", "impossibilidade de apresentar resultados científicos para leitores comuns.", "equivalência entre as expressões usadas para comunicar o resultado.", "obrigatoriedade de descrever integralmente um estudo em cada título."], "key": 1, "skill": 24, "ref": 3, "comment": "“A ciência prova” produz uma certeza ampla e breve; a outra formulação explicita condições. A comparação critica a perda de rigor quando a economia de palavras apaga limites.", "distractors": ["O texto reconhece que economizar palavras ajuda a atrair atenção.", "Correta: a comparação torna visível a tensão entre atração e rigor.", "A dificuldade não é tratada como impossibilidade.", "As formulações têm alcances e efeitos diferentes.", "O texto pede delimitação, sem exigir o estudo integral no título."], "difficulty": "hard"}, {"id": "autoral-5", "stem": "A imagem final do link que “cabe no bolso” ressalta a", "options": ["relação necessária entre o tamanho da tela e a validade da pesquisa.", "vantagem dos links mais curtos para a comprovação de notícias.", "substituição das perguntas do leitor pelas conclusões da manchete.", "diferença entre a facilidade de acesso e a exigência da leitura crítica.", "redução do papel do leitor diante da circulação digital de informações."], "key": 3, "skill": 28, "ref": 5, "comment": "O bolso retoma a portabilidade do telefone; as perguntas que não cabem na manchete figuram a necessidade de ir além do acesso imediato. O leitor permanece agente da interpretação.", "distractors": ["Dimensão da tela não define validade de pesquisa.", "O comprimento do endereço não é discutido como critério.", "O final valoriza as perguntas do leitor.", "Correta: acesso fácil não dispensa investigação e contexto.", "O texto amplia a responsabilidade interpretativa do leitor."], "difficulty": "hard"}]}], "examExamples": [{"id": "enem-ppl-1", "origin": "ENEM", "year": 2023, "collectionNumber": 1, "pages": [12], "skill": 1, "body": ["A animação Vida Maria", "Produzido em computação gráfica 3D e finalizado em 35 mm, o curta-metragem mostra personagens e cenários modelados com texturas e cores pesquisadas e capturadas no sertão cearense, no Nordeste do Brasil, criando uma atmosfera realista e humanizada. O filme nos mostra a história da rotina da personagem Maria José, uma menina de cinco anos de idade que se diverte aprendendo a escrever o nome, mas que é obrigada pela mãe a abandonar os estudos e começar a cuidar dos afazeres domésticos e trabalhar na roça. Enquanto trabalha, ela cresce, casa e tem filhos e depois envelhece, e o ciclo continua a se reproduzir nas outras Marias suas filhas, netas e bisnetas. Disponível em: www.revistaprosaversoearte.com. Acesso em: 1 nov. 2021."], "stem": "Esse fragmento é caracterizado como gênero sinopse, pois apresenta", "options": ["posicionamento da revista sobre a produção da animação.", "relato da história abordada no curta-metragem.", "acontecimentos do cotidiano de uma família.", "história sucinta com poucos personagens.", "fatos da vida de uma menina e seus familiares."], "key": 1, "comment": "A sinopse relata a história que o filme apresenta, como a infância de Maria José e a repetição do ciclo entre gerações. Não é uma avaliação crítica da revista nem um relato autônomo de fatos cotidianos.", "evidence": "O texto menciona o curta-metragem e resume a trajetória da personagem.", "application": "Reconhecer a configuração e os recursos de uma linguagem de divulgação: a sinopse apresenta uma obra audiovisual por meio de um resumo verbal.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 1 na numeração de “Dominando Linguagens”, p. 12. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-13", "origin": "ENEM", "year": 2023, "collectionNumber": 13, "pages": [20], "skill": 2, "body": [], "stem": "Com essa postagem, o enunciador busca", "options": ["divulgar dispositivos legais criados para ajudar no combate a um crime.", "manifestar adesão a uma lei voltada para coibir a prática de um delito.", "incentivar o cidadão a obter informação sobre uma lei por vias informais.", "tornar pública uma lei voltada à criação de perfis nas salas de bate-papo.", "alertar o público usuário de redes sociais sobre mudanças em uma lei vigente."], "key": 0, "comment": "A postagem divulga dispositivos legais relacionados ao combate ao crime, explicando a possibilidade de investigação policial. Não solicita a criação de perfis pelo cidadão nem recomenda informação por canais informais.", "evidence": "O título “Agora é lei!” e a explicação de normas de investigação situam a finalidade informativa da postagem.", "application": "Relacionar um recurso de comunicação à abordagem de um problema social. Leia o aviso como registro da época da prova, sem tomá-lo como orientação jurídica atual.", "preserveLines": false, "figure": "assets/examples/enem-13.png", "figureAlt": "Postagem do Senado Federal: “Agora é lei! Novas regras facilitam operações policiais contra pedofilia”. Explica normas para investigação policial em redes sociais e salas de bate-papo. Uma mão aparece tocando uma tela.", "source": "ENEM 2023 PPL. Item 13 na numeração de “Dominando Linguagens”, p. 20. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-19", "origin": "ENEM", "year": 2023, "collectionNumber": 19, "pages": [26], "skill": 3, "body": ["A solidão nas cidades grandes é muito mais um sinal da precariedade do sentido da comunidade e da convivência, é mais um problema sociocultural do que de escolha individual. Certamente ela reflete a impossibilidade de retornar às florestas, como um dia fez Henry Thoreau. As florestas estão em extinção, assim como, curiosamente, a ideia de humanidade. Resta fugir para a moderna caverna na selva de pedra — sem querer reeditar lugares-comuns — que é a casa de cada um. A solidão é, assim, a categoria política que expressa a nostalgia de uma vivência de si mesmo. Ela é, por isso, a tentativa de preservar a subjetividade e a intimidade consigo mesmo que não tem lugar no contexto de relações sociais transformadas em mercadorias baratas. A sociedade da antipolítica precisa tratar a solidão como uma pena e um mal-estar quando não consegue olhar para a miséria da vez: o fetiche da hiperconectividade, que ilude que não somos sozinhos. TIBURI, M. Disponível em: http://revistacult.uol.com.br. Acesso em: 7 out. 2011."], "stem": "Marcia Tiburi trata de um tema relevante para a sociedade moderna: a convivência interpessoal e a hiperconectividade vivenciada no ciberespaço. O texto classifica-se, quanto ao gênero textual, como artigo de opinião, porque", "options": ["busca resolver a causa da perda de sentido ocorrida na convivência interpessoal.", "procura definir a solidão como uma epidemia que está além das doenças humanas.", "tenta explicar o comportamento do homem contemporâneo tendo como padrão o homem das cavernas.", "objetiva expressar o ponto de vista de que o mal-estar provocado na sociedade decorre da hiperconectividade.", "procura discutir os desejos dos antipolíticos que destroem a intimidade na tentativa de preservar a subjetividade."], "key": 3, "comment": "O artigo apresenta um ponto de vista sobre a solidão e a hiperconectividade, sustentado por avaliações como “fetiche”. A discussão não é uma reportagem neutra nem uma definição médica de epidemia.", "evidence": "A autora associa o mal-estar social à ilusão de não estarmos sozinhos em ambientes hiperconectados.", "application": "Relacionar o conteúdo e a função social de um gênero que participa do debate público por meio de uma posição argumentada.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 19 na numeração de “Dominando Linguagens”, p. 26. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-33", "origin": "ENEM", "year": 2023, "collectionNumber": 33, "pages": [35], "skill": 4, "body": [], "stem": "Nesse texto, ao combinar os gêneros anúncio e manchete de notícia, o autor pretende", "options": ["destacar a variedade de informações divulgadas na mídia.", "aproximar o leitor da realidade vivenciada pelas celebridades.", "criticar a superficialidade de notícias em veículos de comunicação.", "ilustrar a inclusão da população carente em campanhas publicitárias.", "conscientizar o leitor acerca da responsabilidade social nos anúncios."], "key": 2, "comment": "A imagem coloca uma manchete banal sobre uma atriz diante de uma realidade social que não ganha o mesmo destaque. A frase final explicita a crítica à seleção superficial do que se transforma em notícia.", "evidence": "“O problema não é o que vira notícia, mas o que deixa de ser” orienta o contraste entre a manchete e a cena.", "application": "Reconhecer uma posição crítica sobre os usos da comunicação, combinando a leitura da imagem e da frase.", "preserveLines": false, "figure": "assets/examples/enem-33.png", "figureAlt": "Um homem sentado diante de uma moradia segura uma placa: “Atriz é vista atravessando a rua”. Abaixo: “O problema não é o que vira notícia, mas o que deixa de ser”.", "source": "ENEM 2023 PPL. Item 33 na numeração de “Dominando Linguagens”, p. 35. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-48", "origin": "ENEM", "year": 2023, "collectionNumber": 48, "pages": [45], "skill": 5, "body": [], "stem": "Ao utilizar a expressão “be a shame if something were to happen to it”, o pássaro", "options": ["expressa uma ideia de ameaça.", "demonstra uma sugestão de alimento.", "exprime uma sensação de vergonha.", "revela uma ocorrência do passado.", "retrata uma tentativa de aproximação."], "key": 0, "comment": "A expressão funciona como ameaça no contexto da tira. O pássaro elogia a jaqueta, insinua que algo pode acontecer a ela e manda o homem deixar os salgadinhos. Traduzir apenas “shame” como vergonha perde esse sentido pragmático.", "evidence": "O último comando, “Leave the chips”, revela a pressão exercida sobre o interlocutor.", "application": "Associar a expressão em inglês ao tema e à situação: o sentido contextual é uma ameaça velada, não uma simples ocorrência do passado.", "preserveLines": false, "figure": "assets/examples/enem-48.png", "figureAlt": "Tira em quatro quadros. Um pássaro diz “Nice jacket”; o homem responde “Thank you”. O pássaro continua: “Be a shame if something were to happen to it”. Depois ordena “Leave the chips”, e o homem deixa os salgadinhos.", "source": "ENEM 2023 PPL. Item 48 na numeração de “Dominando Linguagens”, p. 45. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-70", "origin": "ENEM", "year": 2022, "collectionNumber": 70, "pages": [59], "skill": 6, "body": ["“We won’t ruin Mars. It’s too big and too good.” said the captain. “You think not? We Earth Men have a talent for ruining big, beautiful things. The only reason we didn’t set up hot-dog stands in the midst of the Egyptian temple of Karnak is because it was out of the way and served no large commercial purpose. And Egypt is a small part of Earth. But here, this whole thing is ancient and different, and we have to set down somewhere and start fouling it up. We’ll call the canal the Rockefeller Canal and the mountain King George Mountain and the sea the Dupont Sea, and there’ll be Roosevelt and Lincoln and Coolidge cities, and it won’t ever be right, when there are the proper names for these places.” BRADBURY, R. And the Moon Be Still as Bright. In: The Martian Chronicles. Londres: Harper Collins, 2014"], "stem": "Nesse fragmento de um conto do autor Ray Bradbury, o personagem revela ao capitão", "options": ["sua dúvida sobre a preservação de lugares antigos.", "seu entusiasmo com a descoberta de um território.", "sua curiosidade sobre o desenvolvimento do Egito.", "sua indiferença com o crescimento dos espaços urbanos.", "sua preocupação com a exploração de um planeta."], "key": 4, "comment": "O personagem teme que os humanos repitam em Marte a exploração e a destruição que praticam na Terra. Os exemplos de interesses comerciais e da troca dos nomes dos lugares sustentam essa preocupação.", "evidence": "“We Earth Men have a talent for ruining big, beautiful things” contrasta com a segurança inicial do capitão.", "application": "Usar a compreensão do inglês para acessar uma reflexão cultural sobre exploração e preservação de territórios.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2022 PPL. Item 70 na numeração de “Dominando Linguagens”, p. 59. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-94", "origin": "ENEM", "year": 2022, "collectionNumber": 94, "pages": [74], "skill": 7, "body": ["Letter to the Editor Michael Gerson’s Oct. 19 Tuesday Opinion column, “The state laboratory of idiocracy strikes again” did not highlight the disservice done to the Black community or any other minority group affected by White history. I wonder about how this will manipulate the perceptions of minorities in the eyes of students. The misguided stereotypes and assumptions perpetuated by these curriculum restrictions will likely prevent Black Americans from expressing themselves safely. It’s plausible to assume that continued miseducation over generations could create a sense of false comfort for Black Americans. Without proper access to history, minorities might begin to forget the oppression they have faced and the injustices they are currently dealing with. Lacking this vital historical education only serves to continue the longstanding issue of misinformation in modern generations. The problems are only the start of the issues that could begin to plague the American education system. Riley Kilcarr, Springfield. Disponível em: www.washingtonpost.com. Acesso em: 29 out. 2021."], "stem": "O autor dessa carta se reporta ao editor de um jornal para", "options": ["criticar uma matéria.", "manipular estudantes.", "atacar uma comunidade.", "revelar uma premonição.", "propagar desinformação."], "key": 0, "comment": "A carta questiona uma coluna publicada pelo jornal por não destacar os efeitos das restrições curriculares sobre minorias. Seu objetivo é criticar a matéria, não manipular alunos ou propagar desinformação.", "evidence": "A referência inicial à coluna de Michael Gerson identifica o texto ao qual o leitor responde.", "application": "Relacionar língua, gênero e uso social: a carta ao editor participa de um debate público ao comentar uma publicação.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2022 PPL. Item 94 na numeração de “Dominando Linguagens”, p. 74. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-111", "origin": "ENEM", "year": 2023, "collectionNumber": 111, "pages": [87], "skill": 8, "body": ["Our physical alienation from India almost inevitably means that we will not be capable of reclaiming precisely the thing that was lost; that we will, in short, create fictions, not actual cities or villages, but invisible ones, imaginary homelands, Indias of the mind. […] It may be argued that the past is a country from which we have all emigrated […], but I suggest that the writer who is out-of-country and even out-of- language may experience this loss in an intensified form. RUSHDIE, S. Imaginary Homelands. Londres: Vintage Books, 2010 (adaptado)."], "stem": "Nesse fragmento de texto, ao abordar a literatura anglo-indiana, o autor Salman Rushdie ressalta a relação entre criação literária e", "options": ["desejo de retorno à terra natal.", "narrativas de espaços urbanos.", "consequências da imigração de origem asiática.", "invisibilidade de autores de literatura indiana.", "distanciamento das raízes culturais."], "key": 4, "comment": "Rushdie relaciona a criação literária ao afastamento das raízes culturais: a experiência de perda leva à construção de pátrias imaginárias. O texto não se concentra na invisibilidade de autores nem num simples desejo de retorno.", "evidence": "“Imaginary homelands” e a condição “out-of-country and even out-of-language” ligam imaginação, deslocamento e pertencimento.", "application": "Reconhecer a literatura em língua estrangeira como expressão de experiências culturais e linguísticas diversas.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 111 na numeração de “Dominando Linguagens”, p. 87. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-128", "origin": "ENEM", "year": 2023, "collectionNumber": 128, "pages": [99], "skill": 9, "body": ["Leão do Norte\n     Sou o coração do folclore nordestino\n     Eu sou Mateus e Bastião do boi-bumbá\n       Sou o boneco do Mestre Vitalino\n     Dançando uma ciranda em Itamaracá\n     Eu sou um verso de Carlos Pena Filho\n         Num frevo de Capiba\n       Ao som da Orquestra Armorial\n              Sou Capibaribe\n        Num livro de João Cabral\n     Sou mamulengo de São Bento do Una\n       Vindo no baque solto de maracatu\n      Eu sou um auto de Ariano Suassuna\n        No meio da Feira de Caruaru\n     Sou Frei Caneca do Pastoril do Faceta\n            Levando a Flor da Lira\n              Pra Nova Jerusalém\n             Sou Luiz Gonzaga\n         E eu sou mangue também\n     Eu sou mameluco, sou de Casa Forte\n    Sou de Pernambuco, sou o Leão do Norte\n       LENINE; PINHEIRO, P. C. Leão do Norte. In:\n                                    LENINE.\n      Olho de peixe. São Paulo, 1993 (fragmento)."], "stem": "A letra da canção expressa a diversidade de danças, sendo uma delas demonstrada no trecho:", "options": ["“Eu sou mameluco, sou de Casa Forte”.", "“Sou de Pernambuco, sou o Leão do Norte”.", "“Sou Luiz Gonzaga / E eu sou mangue também”.", "“Eu sou um auto de Ariano Suassuna / No meio da Feira de Caruaru”.", "“Eu sou Mateus e Bastião do boi-bumbá / Sou o boneco do Mestre Vitalino”"], "key": 4, "comment": "O trecho indicado remete aos personagens do boi-bumbá, manifestação que reúne movimento, música e representação cultural. As outras alternativas citam identidade, autores ou referências culturais que não atendem do mesmo modo ao recorte do comando.", "evidence": "Mateus e Bastião pertencem à manifestação do boi-bumbá evocada pela canção.", "application": "Reconhecer manifestações corporais vinculadas a grupos sociais. Este item enfatiza sua identificação cultural; não exige explicar toda a origem histórica de cada dança.", "preserveLines": true, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 128 na numeração de “Dominando Linguagens”, p. 99. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-143", "origin": "ENEM", "year": 2022, "collectionNumber": 143, "pages": [107], "skill": 10, "body": ["Uma polêmica relacionada à covid-19 com clara relação com a Educação Física foi a discussão sobre a reabertura ou não das academias de ginástica em plena pandemia. Entre os argumentos apresentados pelos que defendiam a abertura estava o de que o exercício teria um efeito protetor contra a covid-19, pelo fortalecimento do sistema imunológico. A realização dessas práticas pode ser importante para a saúde, inclusive com foco na melhoria/manutenção da saúde mental, mas em muitas recomendações há mais um sentido de “ter que fazer”, com caráter “obrigatório”. Outro ponto ignorado diz respeito ao aconselhamento para a realização de exercícios físicos em casa durante a pandemia, considerando aspectos como a habilidade das pessoas para realizarem essas atividades, suas preferências, as condições das residências etc. Entendemos que essas recomendações, algumas vezes de caráter persecutório e descontextualizadas da realidade de muitas pessoas, não favorecem um olhar mais ampliado sobre a saúde. LOCH, M. R. et al. A urgência da saúde coletiva na formação em Educação Física: lições com a covid-19. Ciência & Saúde Coletiva, n. 25, 2020 (adaptado)."], "stem": "Segundo o texto, no contexto da pandemia, a relação entre exercício físico e saúde deveria considerar a", "options": ["necessidade de que as academias se mantivessem abertas para orientação das práticas corporais.", "recomendação de que as atividades físicas atendessem às preferências individuais.", "relevância de adaptar as atividades físicas à realidade social dos sujeitos.", "obrigatoriedade de adotar o hábito de praticar atividades físicas em casa.", "importância de melhorar as defesas orgânicas contra a doença."], "key": 2, "comment": "O texto critica recomendações descontextualizadas e defende considerar habilidades, preferências e condições das residências. A adaptação à realidade social é mais abrangente que a preferência individual, isoladamente.", "evidence": "O autor menciona as condições concretas dos sujeitos ao discutir exercícios em casa.", "application": "Reconhecer a necessidade de adaptar hábitos e práticas corporais às condições e às necessidades de quem os realiza.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2022 PPL. Item 143 na numeração de “Dominando Linguagens”, p. 107. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-150", "origin": "ENEM", "year": 2023, "collectionNumber": 150, "pages": [112], "skill": 11, "body": ["O Esporte Adaptado ou Paradesporto é compreendido como prática que oportuniza às pessoas com deficiência (PcD) o alcance de novos horizontes e perspectivas de vida por meio de vivências motoras, psicológicas e sociais diversificadas. Esse tipo de atividade consiste na possibilidade de prática esportiva para PcD com modificações relacionadas às regras da modalidade ou à maneira como a modalidade se desenvolve. Adicionalmente, o esporte para PcD é geralmente dividido por grupos de deficiência específicos nos quais cada grupo tem história distinta, organização, programa de competição e abordagem diferentes. Registram-se atualmente movimentos esportivos específicos para pessoas surdas, para deficientes físicos, deficientes visuais e para pessoas com deficiência intelectual. Uma grande variedade de modalidades esportivas foram adaptadas para serem praticadas por pessoas com diferentes deficiências, assim como outras modalidades foram criadas exclusivamente para PcD. SIMIM, M. A. M. et al. O estado da arte das pesquisas em esportes coletivos para pessoas com deficiência: uma revisão sistemática. Arquivos de Ciências do Esporte, n. 1, 2018 (adaptado)."], "stem": "De acordo com esse texto, as práticas esportivas para PcD são caracterizadas por", "options": ["terem regras flexíveis em função do desempenho dos atletas em cada modalidade.", "ampliarem perspectivas de vida ao considerarem o desenvolvimento integral das pessoas.", "estarem voltadas para o estímulo à competitividade dos atletas com deficiência.", "buscarem a adesão do público para garantir apoio financeiro às competições.", "serem organizadas sem distinção para grupos de diferentes deficiências."], "key": 1, "comment": "O paradesporto amplia horizontes por meio de vivências motoras, psicológicas e sociais. A resposta considera o desenvolvimento integral, e não apenas competição, desempenho ou apoio financeiro.", "evidence": "A apresentação inicial reúne dimensões motoras, psicológicas e sociais e menciona novas perspectivas de vida.", "application": "Reconhecer adaptações das práticas corporais como possibilidades de participação e interação entre pessoas com condições diferentes.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 150 na numeração de “Dominando Linguagens”, p. 112. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-165", "origin": "ENEM", "year": 2022, "collectionNumber": 165, "pages": [121], "skill": 12, "body": ["Dentre as músicas clássicas que tinham potencial para ganhar as ruas das grandes cidades brasileiras, uma se destacou e acabou se transformando em um recado ao inconsciente coletivo: se as notas ouvidas lá longe são a melodia Für Elise, interpretada ao piano, é um caminhão vendendo gás que se aproxima. Essa história, que torna a obra do compositor alemão Ludwig van Beethoven um meme nacional, começou quando as firmas de venda de gás porta a porta queriam uma solução para substituir o barulho das buzinas e os gritos de “Ó o gás”. Com o objetivo de diminuir a poluição sonora, a prefeitura de São Paulo promulgou a Lei n. 11 016, em 1991, que institui que “Fica proibido o uso da buzina, pelos caminhões de venda de gás engarrafado a domicílio, para anunciar a sua passagem pelas vias e logradouros”. Entregadores de empresas de distribuição de gás recorreram a chips com músicas livres de direitos autorais. No início, não era apenas Für Elise — notas de outros temas clássicos também eram ouvidas. Mas a força da bagatela beethoveniana composta em 1810 acabou se sobrepondo às demais e virou praticamente um símbolo. Disponível em: www.dw.com. Acesso em: 21 dez. 2020 (adaptado)."], "stem": "Ludwig van Beethoven (1770-1827) é mundialmente conhecido como um dos maiores representantes da música de concerto do período romântico. A adoção de uma de suas obras mais difundidas como anúncio de venda de gás engarrafado indica a", "options": ["utilização da música erudita como forma de educar a população em geral.", "manutenção da música europeia nos mais variados aspectos da cultura brasileira.", "contribuição que a obra do compositor alemão tem na diminuição da poluição sonora.", "modificação da função que uma obra artística pode sofrer em diferentes épocas e lugares.", "articulação entre o poder público e as empresas para contornar as limitações das leis de direito autoral."], "key": 3, "comment": "Uma peça de música de concerto passa a anunciar a chegada do caminhão de gás. A questão pede essa mudança de função, não uma suposta finalidade de ensinar música erudita à população.", "evidence": "A melodia de Für Elise torna-se reconhecível como sinal de um serviço cotidiano.", "application": "Reconhecer que uma obra artística pode assumir funções diferentes conforme época, lugar e uso social.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2022 PPL. Item 165 na numeração de “Dominando Linguagens”, p. 121. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-182", "origin": "ENEM", "year": 2021, "collectionNumber": 182, "pages": [130, 131], "skill": 13, "body": [], "stem": "Produzida em 1919, a obra O crítico de arte, de Hausmann, utiliza procedimentos de composição que revelam a", "options": ["visão satírica do artista em relação às convenções da arte burguesa.", "necessidade de reconhecimento social de uma nova estética.", "valorização da vanguarda artística pelo mercado de arte", "beleza da arte em meio às turbulências do pós- guerra.", "fragilidade da formação acadêmica dos novos artistas."], "key": 0, "comment": "A montagem recorta e combina partes de fotografias, letras e objetos para representar de modo satírico o crítico de arte. Essa construção questiona convenções burguesas, em vez de simplesmente buscar aprovação do mercado.", "evidence": "A figura fragmentada e os elementos deslocados produzem estranhamento e ironia.", "application": "Analisar uma produção artística em relação às convenções culturais e às hierarquias que ela põe em questão.", "preserveLines": false, "figure": "assets/examples/enem-182.png", "figureAlt": "O crítico de arte, de Raoul Hausmann, 1919: colagem de um homem composto por recortes, com cabeça e olhos alterados, letras ampliadas no fundo e objetos inseridos. A figura fragmentada produz estranhamento.", "source": "ENEM 2021 PPL. Item 182 na numeração de “Dominando Linguagens”, p. 130, 131. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-192", "origin": "ENEM", "year": 2023, "collectionNumber": 192, "pages": [137], "skill": 14, "body": [], "stem": "Sob a perspectiva em que o artista deve trabalhar com as coisas que o tocam profundamente, a singularidade da obra Bastidores, produzida com objetos do cotidiano e de pouco valor material, mostra a boca, que expressa uma", "options": ["situação religiosa afro-brasileira que envolve grande parte da população.", "condição particular da artista, deslocada de umcontexto sociocultural.", "situação histórica em que as mulheres ainda bordavam em bastidores.", "condição vivida por parte das mulheres afro- brasileiras trabalhadoras.", "situação que se sugere, mas que não se aplica, a parcelas da população."], "key": 3, "comment": "A boca costurada numa fotografia sobre tecido, colocada num bastidor de bordado, remete ao silenciamento vivido por mulheres negras trabalhadoras. O sentido ultrapassa uma experiência individual desligada do contexto sociocultural.", "evidence": "O contraste entre o objeto cotidiano de costura e a intervenção na boca conduz à leitura de silenciamento.", "application": "Reconhecer uma expressão artística de experiências sociais e identidades historicamente marginalizadas, valorizando sua dimensão cultural.", "preserveLines": false, "figure": "assets/examples/enem-192.png", "figureAlt": "Bastidores, de Rosana Paulino, 1997: fotografia de uma mulher negra impressa sobre tecido e montada em bastidor de bordado; a boca está coberta por costura escura.", "source": "ENEM 2023 PPL. Item 192 na numeração de “Dominando Linguagens”, p. 137. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-203", "origin": "ENEM", "year": 2023, "collectionNumber": 203, "pages": [145], "skill": 15, "body": ["O grande hall do hotel estava repleto. [...] Os criados passavam apressados, erguendo numa azáfama os pratos de metal. Ao alto, os ventiladores faziam um rumor de colmeias. Senhoras e cavalheiros, perfeitamente felizes, as senhoras quase todas com largos boás de plumas brancas, chalravam e sorriam. Estávamos bem na bizarra sociedade de entalhe que é o escol dos hotéis. Alta, longa, comprida, com uma cintura de esmaltes translúcidos e o ar empoado de uma íntima do general Lafayette, a escritora americana cuja admiração por Gonçalves Dias chegara a fazê-la estudar e propagar o Brasil, mastigava gravemente. Logo ao lado, um grupo de engenheiros, também americanos, bebia, com gargalhadas brutais e decerto inconvenientes, champanhe Mumm. [...] De vez em quando parava à porta um novo hóspede, hesitava, percorria com o olhar a extensa fila de mesas onde o debinage se acalorava. A um canto, Mlles. Peres, filhas de um rico argentino, yatch-recorderman nas horas vagas e vendedor de gado nas outras, perlavam risadinhas de flerte para o solitário e divino Alberto Guerra, seguro dos seus bíceps, dos seus brilhantes e quiçá dos seus versos. JOÃO DO RIO. Dentro da noite. São Paulo: Antiqua, 2002 (fragmento)."], "stem": "Nessa descrição, o narrador traça um panorama sociocultural das primeiras décadas do século XX. Sua perspectiva revela uma", "options": ["percepção irônica da importação de valores e modismos.", "euforia generalizada com as facilidades da modernidade.", "visão otimista sobre as atitudes da mulher emancipada.", "adesão propagandística aos gostos burgueses e ao luxo.", "preocupação nacionalista com a integridade da língua."], "key": 0, "comment": "O narrador apresenta comportamentos e modismos das elites com distanciamento irônico. As expressões avaliativas e os detalhes da cena não indicam adesão entusiasmada ao luxo ou aos valores importados.", "evidence": "“Bizarra sociedade” e “gargalhadas brutais e decerto inconvenientes” desfazem uma leitura de elogio.", "application": "Relacionar a visão do texto literário ao panorama sociocultural das primeiras décadas do século XX.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 203 na numeração de “Dominando Linguagens”, p. 145. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-215", "origin": "ENEM", "year": 2023, "collectionNumber": 215, "pages": [152], "skill": 16, "body": ["Da calma e do silêncio\n            Quando eu morder\n                a palavra,\n                  por favor,\n             não me apressem,\n               quero mascar,\n            rasgar entre os dentes,\n          a pele, os ossos, o tutano\n                do verbo,\n             para assim versejar\n            o âmago das coisas...\n                                          [...]\n            Quando meus pés\n           abrandarem na marcha,\n                  por favor,\n              não me forcem.\n            Caminhar para quê?\n            Deixem-me quedar,\n            deixem-me quieta,\n            na aparente inércia.\n         Nem todo viandante\n              anda estradas,\n           há mundos submersos,\n             que só o silêncio\n            da poesia penetra.\n  EVARISTO, C. Poemas de recordação e outros movimentos.\n                     Rio de Janeiro: Malê, 2021 (fragmento)."], "stem": "Na reflexão sobre motivos e soluções do trabalho com a palavra, o eu lírico defende que a poesia", "options": ["reflete as limitações inerentes à sua matéria- prima.", "é um produto relacionado ao sentimento de angústia.", "exige o engajamento social para a sua plena realização.", "requer um tempo próprio de amadurecimento e plenitude.", "deve desvincular-se de questões de inspiração metafísica."], "key": 3, "comment": "O eu lírico pede que não o apressem e associa o trabalho poético a penetrar o âmago das coisas. O silêncio e a aparente inércia são apresentados como condições de elaboração, não como impossibilidade de criar.", "evidence": "Os pedidos “não me apressem” e “não me forcem” marcam o tempo próprio da criação.", "application": "Relacionar imagens, voz e construção do poema a uma concepção de trabalho literário baseada no amadurecimento da palavra.", "preserveLines": true, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 215 na numeração de “Dominando Linguagens”, p. 152. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-234", "origin": "ENEM", "year": 2023, "collectionNumber": 234, "pages": [163], "skill": 17, "body": ["O voluntário Quem não sabe o efeito produzido à beira do rio pela notícia da declaração da guerra entre o Brasil e o Paraguai? Nas classes mais favorecidas da fortuna, nas cidades principalmente, o entusiasmo foi grande e duradouro. Mas entre o povo miúdo o medo do recrutamento para voluntário da Pátria foi tão intenso que muitos tapuios se meteram pelas matas e pelas cabeceiras dos rios, e ali viveram como animais bravios sujeitos a toda a espécie de privações. [...] Coisa terrível que era então o recrutamento! Esse meio violento de preencher os quadros do exército era ao tempo da guerra posto em prática com barbaridade e tirania, indignas dum povo que pretende foros de civilizado. Suplícios tremendos eram infligidos aos que, fugindo a uma obrigação não compreendida, ousavam preferir a paz do trabalho e o sossego do lar à ventura de se deixarem cortar em postas na defesa das estâncias rio-grandenses e das aldeolas de Mato Grosso. SOUZA, I. Contos amazônicos. Jundiaí: Cadernos do Mundo Inteiro, 2018 (fragmento)."], "stem": "Para descrever o modo como indígenas e ribeirinhos eram recrutados para lutarem como “voluntários da Pátria”, o texto de Inglês de Souza", "options": ["enfatiza a capacidade de resiliência dos tapuios.", "põe em evidência a brutalidade do alistamento compulsório.", "ironiza a importância atribuída à guerra pelas elites da época.", "relativiza a prevalência da disputa bélica sobre a natureza pacífica.", "critica a incompreensão da população acerca das motivações do conflito."], "key": 1, "comment": "O contraste entre o nome “voluntário” e o recrutamento violento expõe a coerção. “Barbaridade”, “tirania” e “suplícios” mostram que a crítica recai sobre o alistamento compulsório, não sobre a resistência dos recrutados.", "evidence": "A população foge de uma obrigação não compreendida, apesar do rótulo de voluntariado.", "application": "Reconhecer no patrimônio literário conflitos sociais e valores humanos que continuam discutíveis, como violência, liberdade e desigualdade.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 234 na numeração de “Dominando Linguagens”, p. 163. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-254", "origin": "ENEM", "year": 2023, "collectionNumber": 254, "pages": [176], "skill": 18, "body": ["Plantas superpoderosas A bióloga Joanne Chory já tinha 60 anos e um diagnóstico de Parkinson quando decidiu se dedicar a um projeto que capturasse gás carbônico da atmosfera — coisa que as plantas fazem regularmente há 2,8 bilhões de anos. Para isso, a pesquisadora começou a estudar algumas espécies e alterá-las por meio de técnicas de horticultura e manipulação genética. A ideia é que capturem mais carbono e o armazenem em suas raízes. Uma dessas plantas, um tipo de mostarda, já cresce no delta do rio Mississipi. Caso funcione, a pesquisa tem potencial para diminuir em 46% o excesso de CO2 jogado anualmente na atmosfera. “Provavelmente não estarei aqui para ver os resultados. Mas prefiro ser parte da solução a me sentar e reclamar”, diz Joanne. Que as superplantas criadas pela bióloga vinguem e vicejem! CARNEIRO, F. Disponível em: https://veja.abril.com.br. Acesso em: 23 out. 2021 (adaptado)."], "stem": "Esse texto descreve a pesquisa inovadora realizada por uma bióloga de 60 anos com diagnóstico de Parkinson. O trecho que permite uma referência indireta a essa condição física é", "options": ["“decidiu se dedicar a um projeto que capturasse gás carbônico”.", "“a pesquisadora começou a estudar algumas espécies”.", "“Caso funcione, a pesquisa tem potencial para diminuir em 46% o excesso de CO2”.", "“‘Provavelmente não estarei aqui para ver os resultados’”.", "“Que as superplantas criadas pela bióloga vinguem e vicejem!”."], "key": 3, "comment": "A fala sobre não estar presente para ver os resultados retoma indiretamente a idade e a condição física apresentadas no início. É necessário relacionar esse trecho à informação anterior, sem interpretá-lo como diagnóstico médico.", "evidence": "A expectativa de ausência futura ganha sentido ao ser lida em relação à apresentação da pesquisadora.", "application": "Identificar relações entre partes do texto e compreender como uma informação anterior participa da progressão temática.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 254 na numeração de “Dominando Linguagens”, p. 176. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-274", "origin": "ENEM", "year": 2023, "collectionNumber": 274, "pages": [186], "skill": 19, "body": [], "stem": "Nesse cartum, a predominância da função poética da linguagem manifesta-se na", "options": ["ênfase dada à dificuldade de compreensão de um atlas.", "articulação entre a expressão verbal e as imagens representadas.", "singularidade da percepção da autora sobre a área de geografia.", "construção de uma representação cartográfica diferente.", "forma de organização das informações do mapa- múndi"], "key": 1, "comment": "A frase brinca com a relação sonora e gráfica entre “mar” e “múndi”, enquanto o desenho transforma um mapa aberto em formas semelhantes a rostos. A elaboração verbal e visual da mensagem sustenta a função poética.", "evidence": "“Qualquer mar é múndi” dialoga com “mapa-múndi” e com a imagem que se transforma.", "application": "Analisar a função predominante pelo trabalho sobre a forma da mensagem. A função poética pode aparecer num cartum, não apenas num poema.", "preserveLines": false, "figure": "assets/examples/enem-274.png", "figureAlt": "Cartum de Laerte. Frase: “Quando tudo se confunde, qualquer mar é múndi”. Uma pessoa segura um mapa aberto, cujas partes também formam rostos; uma rosa dos ventos aparece ao centro.", "source": "ENEM 2023 PPL. Item 274 na numeração de “Dominando Linguagens”, p. 186. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-283", "origin": "ENEM", "year": 2023, "collectionNumber": 283, "pages": [192], "skill": 20, "body": ["A sobrevivência dos pomeranos Ocorrem no Brasil atual casos como o da língua falada pelos pomeranos, que imigraram para o Brasil devido à Segunda Guerra Mundial, e que conseguiu manter-se viva em pequenas comunidades do Rio Grande do Sul e do Espírito Santo. Essa língua, em pleno uso e transmissão no Brasil, não é mais falada na Europa Central, sua região de origem. Após a guerra, a região onde ficava Pomerode foi incorporada à Polônia pela força do regime soviético. Quanto à etnia dos pomeranos, praticamente foi extinta e os sobreviventes dispersados pela Polônia. Mas a língua permanece viva no Brasil. CASAL JR., M. Disponível em: http://desafios.ipea.gov.br. Acesso em: 30 out. 2021 (adaptado)."], "stem": "De acordo com esse texto, a língua falada pelos pomeranos", "options": ["continua sendo transmitida em Pomerode, na Polônia.", "permanece preservada em algumas regiões do Brasil.", "apresenta características distintas no Brasil.", "contribui para o isolamento da Polônia no Leste Europeu.", "foi dispersada por ação do regime soviético."], "key": 1, "comment": "Segundo o texto, a língua continua em uso e é transmitida em comunidades brasileiras. A resposta identifica a preservação linguística, sem afirmar que a língua permanece na região europeia mencionada.", "evidence": "O texto localiza sua transmissão em comunidades do Rio Grande do Sul e do Espírito Santo.", "application": "Reconhecer a língua como patrimônio e elemento de memória e identidade de uma comunidade.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 283 na numeração de “Dominando Linguagens”, p. 192. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-292", "origin": "ENEM", "year": 2023, "collectionNumber": 292, "pages": [200], "skill": 21, "body": [], "stem": "A articulação entre os recursos verbais e não verbais utilizados na construção do texto tem como objetivo", "options": ["explicar para o público os efeitos de conteúdos enganosos.", "expor a fragilidade de tecnologias digitais na manipulação de dados.", "promover a partilha de conhecimentos por meio de recursos tecnológicos.", "orientar práticas para o reconhecimento de mensagens perigosas em ambientes digitais.", "incentivar a adoção de comportamentos adequados na disseminação de informações."], "key": 4, "comment": "O cartaz combina a recusa visual das fake news com a orientação de ler todo o texto antes de compartilhar. Procura mudar a conduta de quem dissemina informações, sem oferecer um método completo para detectar mensagens perigosas.", "evidence": "“O título é impactante? Cuidado! Antes de compartilhar uma notícia, leia todo o seu texto” acompanha a imagem do celular e a palavra “NÃO”.", "application": "Reconhecer recursos verbais e visuais utilizados para estimular uma mudança de comportamento.", "preserveLines": false, "figure": "assets/examples/enem-292.png", "figureAlt": "Campanha do CNJ com um celular: “Fake news NÃO”. Orientação: “O título é impactante? Cuidado! Antes de compartilhar uma notícia, leia todo o seu texto”.", "source": "ENEM 2023 PPL. Item 292 na numeração de “Dominando Linguagens”, p. 200. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-301", "origin": "ENEM", "year": 2023, "collectionNumber": 301, "pages": [209], "skill": 22, "body": ["TEXTO I A nova opinião pública e as redes digitais Todas as vezes que os injustiçados do mundo ganham espaço nas telinhas dos gadgets de última geração e nas correntes caudalosas de e-mails, e o barulho digital é tanto que chega até aos veículos de comunicação tradicionais, muita gente destaca as boas qualidades do que chamam de uma nova opinião pública. É difícil não nos confrontarmos com as novas formas que a sociedade utiliza para se inteirar, integrar-se, persuadir, manipular, controlar, aprender, fazer-se ver e ser vista, conversar e fofocar. Isso porque, o tempo todo, as multidões estão opinando, capturando imagens em quantidade descomunal e disponibilizando-as facilmente para audiências abrangentes. Essa produção midiática da multidão, muitas vezes formatada sem preocupações técnicas, éticas e estéticas, com certeza não contribui para a consolidação de uma conversação democrática, que respeite a alteridade, dê tempo ao contraditório e à comunicação. Essa nova opinião pública é rápida em linchamentos simbólicos e em expressar preconceitos em mensagens rapidinhas, de 140 caracteres. AMADEU, S. Disponível em: www.sescsp.org.br. Acesso em: 26 nov. 2021 (adaptado).", "TEXTO II Uma nova opinião pública. Será? A internet inverteu o ecossistema comunicacional. O difícil não é falar. Agora, o grande problema é ser ouvido. Todavia, quando alguém fala algo que todos queriam ouvir, uma onda imediatamente se forma no oceano informacional e pode gerar ações concretas nas ruas, nos mercados, nas bolsas de valores. A rede é um articulador coletivo de diversas causas. Não podemos ter a ilusão de que somente ideias democratizantes e ligadas à nobre causa da defesa ambiental é que geram adeptos. Uma análise mais aprofundada das ações e do ativismo em rede permite observar que cada vez mais se formam redes de opinião distintas e muitas vezes opostas. Por fim, também é preciso notar que a internet é uma rede de arquitetura distribuída. Por isso, sua natureza é mais propícia às ações democratizadoras, livres e favoráveis ao compartilhamento do que às posturas que visam simplesmente à dominação, ao controle autoritário e ao impedimento da troca de arquivos digitais. NASSAR, P. Disponível em: www.sescsp.org.br. Acesso em: 26 nov. 2021 (adaptado)"], "stem": "Com relação à produção da opinião pública na contemporaneidade, os textos I e II divergem sobre o(a)", "options": ["compreensão da internet como espaço de construção democrática.", "uso mal-intencionado das tecnologias de informação e comunicação.", "entendimento da internet como meio de exposição de pensamentos.", "impacto das postagens nas redes de defensores de causas minoritárias.", "falta de curadoria dos conteúdos disponíveis nos ambientes virtuais."], "key": 0, "comment": "Os dois textos tratam da opinião pública digital, mas diferem na avaliação de seu potencial democrático. O primeiro enfatiza linchamentos e preconceitos; o segundo considera a arquitetura distribuída mais propícia a ações democratizadoras.", "evidence": "A divergência aparece entre a crítica à conversação digital e a valorização das possibilidades de compartilhamento.", "application": "Confrontar pontos de vista em textos sobre o mesmo assunto. O tema comum não elimina diferenças de avaliação.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 301 na numeração de “Dominando Linguagens”, p. 209. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-313", "origin": "ENEM", "year": 2023, "collectionNumber": 313, "pages": [218], "skill": 23, "body": ["A palavra saudade faz parte do vocabulário cotidiano dos portugueses e, também, do povo brasileiro. Mas afinal, qual é a sua verdadeira origem? Existem algumas especulações sobre a origem de saudade. Há quem defenda que a palavra vem do árabe saudah. Outros entendem que a sua origem vem do latim sólitas, que significa solidão. Alguns especialistas indicam que palavras como saud, saudá e suaida significam “sangue pisado” e “preto dentro do coração”. A metáfora perfeita para alguém que carrega no seu coração uma profunda tristeza, tristeza esta que pode ser causada pela saudade. Os árabes utilizam o termo as-saudá quando querem se referir a uma doença do fígado, diagnosticada por eles como “melancolia do paciente”. Em certos idiomas, o significado de solitate foi mantido, como é o caso do castelhano (soledad), do italiano (solitudine) ou do francês (solitude). Em português e no galego (soidade), alterou-se com o tempo. Assim sendo, quando alguém dizia “tenho saudades de casa” significava que sentia “solidão” por não estar em casa. De qualquer forma, os portugueses foram atribuindo outros significados a saudade. Dizem até que passou a fazer parte do dicionário dos portugueses no tempo dos Descobrimentos Marítimos. Saudade definia a solidão que os portugueses tinham da sua terra, familiares e amigos, quando estes partiam para o Brasil. Disponível em: www.natgeo.pt. Acesso em: 24 nov. 2021 (adaptado)."], "stem": "Esse texto, que trata da acepção da palavra “saudade” em vários idiomas, tem como objetivo", "options": ["questionar sua evolução histórica.", "especular sobre suas origens etimológicas.", "explicar seu processo de dicionarização.", "problematizar seus diferentes sentidos na sociedade.", "defender a tese acerca de sua origem desconhecida."], "key": 1, "comment": "O texto reúne hipóteses sobre a origem da palavra saudade, recorrendo a línguas e sentidos diferentes. O objetivo é especular sobre origens etimológicas, sem estabelecer uma certeza definitiva.", "evidence": "“Há quem defenda” e “outros entendem” apresentam hipóteses, em lugar de uma única origem comprovada.", "application": "Inferir o objetivo do produtor pelo modo como seleciona e apresenta informações e argumentos.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 313 na numeração de “Dominando Linguagens”, p. 218. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-326", "origin": "ENEM", "year": 2023, "collectionNumber": 326, "pages": [227], "skill": 24, "body": ["Uma marca de eletrodomésticos que retornou para o mercado brasileiro posicionou painéis em pontos estratégicos da cidade de São Paulo com frases que trazem histórias reais de mulheres que desafiaram padrões e estereótipos, com a premissa de trazer uma reflexão sobre o Dia da Igualdade Feminina. Cada uma das 9 frases traz um contraponto instigante e atualiza uma nova ideia em sintonia com o ambiente, dialogando com a cidade, como “O cara que inventou a cerveja foi uma mulher”, perto de bares, e “O melhor artilheiro da seleção é uma mulher nordestina”, em frente a estádios de futebol. Frases como “O pai do wi-fi foi uma mulher, atriz e refugiada”; “O gênio por trás do GPS foi uma mulher negra”; “O arquiteto que projetou o MASP foi uma mulher imigrante”; “O ator que mais vezes venceu o Oscar foi uma mulher”; “O cientista precursor da energia limpa foi uma mulher”; “O primeiro piloto de testes da história foi uma mulher” e “O autor do primeiro romance do mundo foi uma mulher japonesa” estavam presentes em 15 pontos da cidade de São Paulo. ALVES, S. Disponível em: www.b9.com.br. Acesso em: 5 nov. 2021 (adaptado)."], "stem": "Ao provocar a reflexão sobre o Dia da Igualdade Feminina, a campanha descrita nesse texto fundamenta-se no(a)", "options": ["oposição proposital entre as referências de gênero presentes nas frases.", "relação entre os dizeres do painel e o local estratégico de instalação.", "alusão a grandes feitos científicos que são amplamente conhecidos.", "padrão das frases que favorece a assimilação da mensagem.", "apresentação de temáticas muito presentes no dia a dia."], "key": 0, "comment": "A campanha contrasta intencionalmente referências masculinas, como “o pai” e “o arquiteto”, com a informação de que o feito é de uma mulher. A localização dos painéis ajuda a campanha, mas não é o fundamento central pedido pelo comando.", "evidence": "A repetição de uma expectativa masculina seguida de “foi uma mulher” quebra estereótipos.", "application": "Reconhecer uma estratégia argumentativa: o contraste linguístico provoca revisão de uma expectativa social.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 326 na numeração de “Dominando Linguagens”, p. 227. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-343", "origin": "ENEM", "year": 2021, "collectionNumber": 343, "pages": [238], "skill": 25, "body": ["Bola na rede Futebol de várzea, pelada, baba, racha, rachão. Os nomes podem ser diferentes em cada pedaço do Brasil, mas bater uma bolinha é mesmo uma paixão nacional. Os dados do suplemento de esporte da PNAD 2015 mostraram que o futebol foi a principal modalidade esportiva praticada no Brasil, com 15,3 milhões de adeptos. É claro que o fato de o nosso país ter um futebol profissional consagrado, com times que arrebatam torcidas e revelam jogadores, é uma influência positiva, mas a maioria dessa galera que gosta de correr atrás da bola não tem nenhuma pretensão profissional com o esporte. Para eles, tão bom quanto marcar um gol é juntar velhos amigos, fazer novas amizades e se divertir muito. BENEDICTO, M.; MARLI, M. Retratos: a revista do IBGE, n. 2, ago. 2017(adaptado)."], "stem": "Ao abordar a temática do futebol no Brasil, o texto apresenta diferentes nomes para uma partida do esporte. Ao fazer isso, fica evidente que", "options": ["os torcedores enaltecem seus times favoritos.", "o futebol é um esporte presente em todo o Brasil.", "a linguagem do futebol reaproxima pessoas distantes.", "os campeonatos da modalidade propiciam a integração do Brasil.", "as regiões do país imprimem um estilo próprio para o jogo de futebol."], "key": 1, "comment": "A variedade de denominações mostra a presença do futebol em diferentes partes do país. Os nomes distintos não demonstram, por si só, estilos diferentes de jogar nem o papel integrador de campeonatos.", "evidence": "“Futebol de várzea, pelada, baba, racha, rachão” é relacionado aos diferentes lugares do Brasil.", "application": "Identificar diversidade lexical e relacioná-la a usos regionais e sociais da língua, sem hierarquizar as denominações.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2021 PPL. Item 343 na numeração de “Dominando Linguagens”, p. 238. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-352", "origin": "ENEM", "year": 2023, "collectionNumber": 352, "pages": [244], "skill": 26, "body": ["Terça-feira, 30 de maio de 1893. Eu gosto muito de todas as festas de Diamantina; mas quando são na igreja do Rosário, que é quase pegada à chácara de vovó, eu gosto ainda mais. Até parece que a festa é nossa. E este ano foi mesmo. Foi sorteada para rainha do Rosário uma ex-escrava de vovó chamada Júlia e para rei um negro muito entusiasmado que eu não conhecia. Coitada de Júlia! Ela vinha há muito tempo ajuntando dinheiro para comprar um rancho. Gastou tudo na festa e ainda ficou devendo. Agora é que eu vi como fica caro para os pobres dos negros serem reis por um dia. Júlia com o vestido e a coroa já gastou muito. Além disso, teve de dar um jantar para a corte toda. A rainha tem uma caudatária que vai atrás segurando na capa que tem uma grande cauda. Esta também é negra da chácara e ajudou no jantar. Eu acho graça é no entusiasmo dos pretos neste reinado tão curto. Ninguém rejeita o cargo, mesmo sabendo a despesa que dá! MORLEY, H. Minha vida de menina. São Paulo: Cia. das Letras, 1998."], "stem": "O trecho apresenta marcas textuais que justificam o emprego da linguagem coloquial. O tom informal do discurso se deve ao fato de que se trata de um(a)", "options": ["narrativa regionalista, que procura reproduzir as características mais típicas da região, como as falas dos personagens e o contexto social a que pertencem.", "carta pessoal, escrita pela autora e endereçada a um destinatário específico, com o qual ela tem intimidade suficiente para suprimir as formalidades da correspondência oficial.", "registro no diário da autora, conforme indicam a data, o emprego da primeira pessoa, a expressão de reflexões pessoais e a ausência de uma intenção literária explícita na escrita.", "narrativa de memórias, na qual a grande distância temporal entre o momento da escrita e o fato narrado impõe o tom informal, pois a autora tem dificuldade de se lembrar com exatidão dos acontecimentos narrados.", "narrativa oral, em que a autora deve escrever como se estivesse falando para um interlocutor, isto é, sem se preocupar com a norma-padrão da língua portuguesa e com referências exatas aos acontecimentos mencionados."], "key": 2, "comment": "Data, primeira pessoa, comentários pessoais e referências familiares caracterizam uma escrita de diário, explicando o registro coloquial. Esses elementos distinguem o trecho de carta, relato oral ou memória escrita muito depois dos fatos.", "evidence": "O registro datado e expressões como “vovó” e “eu acho graça” situam a interação pessoal da escrita.", "application": "Relacionar uma variedade de registro à situação de uso. A linguagem e as avaliações da narradora são vozes históricas do texto, não juízos do app.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 352 na numeração de “Dominando Linguagens”, p. 244. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-359", "origin": "ENEM", "year": 2023, "collectionNumber": 359, "pages": [250], "skill": 27, "body": ["Proclamação do amor antigramática\n“Dá-me um beijo”, ela me disse,\nE eu nunca mais voltei lá.\nQuem fala “dá-me” não ama,\nQuem ama fala “me dá”\n“Dá-me um beijo” é que é correto,\nÉ linguagem de doutor,\nMas “me dá” tem mais afeto,\nBeijo me-dado é melhor.\nA gramática foi feita\nPor um velho professor,\nPor isso é tão má receita\nPra dizer coisas de amor.\nO mestre pune com zero\nQuem não diz “amo-te”. Aposto\nQue em casa ele é mais sincero\nE diz pra mulher: “te gosto”\nDelírio dos olhos meus,\nEstás ficando antipática.\nPelo diabo ou por deus\nManda às favas a gramática.\nFala, meu cheiro de rosa,\nDo jeito que estou pedindo:\n“Hoje estou menas formosa,\nCom licença, vou se indo”.\nComete miles de erros,\nMistura tu com você,\nE eu proclamarei aos berros:\n“Vós és o meu bem querer”.\n  LAGO, M. Disponível em: www.mariolago.com.br. Acesso em: 30\n                                                           out. 2021."], "stem": "Nesse poema, o eu lírico defende o uso de algumas estruturas consideradas inadequadas na norma- padrão da língua. Esse uso, exemplificado por “me dá” e “te gosto”, é legitimado", "options": ["pelo contexto de situação discutido ao longo do poema.", "pelas características enunciativas requeridas pelo gênero poema.", "pela interlocução construída entre o eu lírico e os leitores do poema.", "pela mobilização da função poética da linguagem na composição do texto.", "pelo reconhecimento do valor social da variedade de prestígio em textos escritos."], "key": 0, "comment": "O eu lírico defende formas coloquiais na expressão do afeto. O contexto amoroso legitima essas escolhas, em contraste com a solenidade de formas associadas à correção gramatical.", "evidence": "“Me dá” e “te gosto” são contrapostos às formas que o eu lírico considera menos afetivas.", "application": "Reconhecer o uso da norma padrão em relação à situação de comunicação, incluindo efeitos expressivos produzidos pelo contraste de registros.", "preserveLines": true, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 359 na numeração de “Dominando Linguagens”, p. 250. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-368", "origin": "ENEM", "year": 2023, "collectionNumber": 368, "pages": [257], "skill": 28, "body": ["No tempo em que assistíamos televisão no meio da praça O que eu vou contar nestas próximas linhas não fará sentido para os leitores mais jovens, mas houve um tempo em que assistíamos televisão no meio da praça. Nessa fase, a propriedade de aparelhos ainda era restrita às camadas mais abastadas. Seja no meio de uma praça pública, seja na sala de casa, a televisão cumpriu um importante papel de sociabilização, mesmo que de forma mitigada. Isso porque, ao contrário do que acontecia na antiguidade, as praças não eram (como ainda não são) espaços de convivência pública ativa, no máximo um lugar para gastar o tempo, bater um papo. Naqueles tempos, os aparelhos de TV nas praças reverteram um pouco dessa lógica. Ao que parece, está se inaugurando no Brasil um novo tempo no campo da pesquisa sobre a televisão e sua inserção sociocultural nas camadas populares. Essas pesquisas não podem e não devem ignorar,especialmente, a intensa concentração desses veículos nas mãos de poucas famílias e grupos econômicos, sob o risco de a televisão no Brasil continuar centrada num modelo antidemocrático, antimediador, intransitivo, tendo como consequência direta a limitação crescente da participação da população nas instâncias públicas de decisão (a televisão é uma concessionária de serviço público), só que agora com o agravante da falsa sensação de que a comunicação se tornou mais democrática com a internet. Que a televisão permaneça por muitos e muitos anos, mas que o seu atual modelo tenha seus dias contados! Quem sabe com isso um dia voltemos para o meio da praça, não mais para assistir TV, mas para fazermos valer uma cultura de participação política realmente ativa e instruída, como uma democracia de fato merece. ARAÚJO, F. P. Disponível em: www.observatoriodaimprensa.com.br. Acesso em: 30 out. 2021 (adaptado)."], "stem": "Embora reconheça o impacto social da televisão e seu importante papel de sociabilização ao longo do tempo, o texto defende que essa tecnologia passe por mudanças que contribuam para", "options": ["ampliar o acesso a aparelhos de TV para toda a população.", "transformar a praça pública em um lugar de convivência social.", "divulgar os resultados de pesquisas sobre sua inserção social.", "fomentar uma maior participação da população nas esferas públicas.", "viabilizar sua permanência no futuro em contraposição ao advento da internet."], "key": 3, "comment": "O autor reconhece a sociabilização promovida pela televisão, mas critica a concentração de poder e a pouca participação pública. As mudanças desejadas têm finalidade política e social mais ampla que ampliar a posse de aparelhos.", "evidence": "O último parágrafo pede uma cultura de participação política ativa e instruída.", "application": "Reconhecer impactos sociais das tecnologias e distinguir acesso a aparelhos de participação efetiva na comunicação pública.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 368 na numeração de “Dominando Linguagens”, p. 257. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-382", "origin": "ENEM", "year": 2023, "collectionNumber": 382, "pages": [266], "skill": 29, "body": ["É vantajoso que as crianças possam entender o funcionamento por trás da tecnologia que está presente em diversos aspectos da vida cotidiana, aproveitando a curiosidade infantil como impulso inicial. A computação ajuda a desenvolver o raciocínio, a melhorar a comunicação e a trabalhar a capacidade de resolver problemas. Os computadores executam tarefas por meio de comandos dados em uma programação. Essa, por sua vez, é feita com linguagens próprias, que funcionam como uma espécie de “idioma”, por meio do qual o programador se comunica com as máquinas. Porém, mais do que dominar essas linguagens, o programador precisa empregar a lógica computacional. O programador precisa expressar em seu código as condições e seus efeitos, como “se acontecer A, faça B, a não ser que haja X, então faça C”. A escrita de um algoritmo é repleta de condições interconectadas, do tipo “se”, “então”, “senão”, “ou”, “até que”, “enquanto” etc. Por isso, para programar, é necessário compreender esse tipo de raciocínio. Para as crianças, isso é tarefa fácil; afinal elas têm uma capacidade incrível de assimilar informações novas. Disponível em: https://catracalivre.com.br. Acesso em: 25 nov. 2021."], "stem": "Esse texto promove uma reflexão sobre o ensino de programação na infância. A defesa da proposta está ancorada na caracterização da programação com base na sua", "options": ["conexão com aspectos lúdicos da infância.", "autonomia em relação ao raciocínio lógico.", "presença crescente no dia a dia das pessoas.", "similaridade com o funcionamento das línguas.", "capacidade de inovação na resolução de tarefas."], "key": 3, "comment": "A programação é descrita como uma linguagem própria, com comandos e relações condicionais. A comparação com um idioma estrutura a defesa de ensinar seu funcionamento às crianças.", "evidence": "“Se”, “então” e “senão” exemplificam a articulação lógica dos comandos e são apresentados como linguagem.", "application": "Identificar a linguagem que dá suporte a uma tecnologia, sem confundir programação com ausência de raciocínio lógico.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2023 PPL. Item 382 na numeração de “Dominando Linguagens”, p. 266. Gabarito conferido na seção de respostas do material enviado."}, {"id": "enem-ppl-399", "origin": "ENEM", "year": 2017, "collectionNumber": 399, "pages": [276], "skill": 30, "body": ["A inteligência está na rede", "Pergunta: Há tecnologias que melhoram a vida humana, como a invenção do calendário, e outras que revolucionam a história humana, como a invenção da roda. A internet, o iPad, o Facebook, o Google são tecnologias que pertencem a que categoria? Resposta: À das que revolucionam a história. O que está acontecendo no mundo de hoje é semelhante ao que se passou com a sociedade agrária depois da prensa móvel de Gutenberg. Antes, o conhecimento estava concentrado em oligopólios. A invenção de Gutenberg começou a democratizar o conhecimento, e as instituições do feudalismo entraram num processo de atrofia. A novidade afetou a Igreja Católica, as monarquias, os poderes coloniais e, com o passar do tempo, resultou nas revoluções na América Latina, nos Estados Unidos, na França. Resultou na democracia parlamentar, na reforma protestante, na criação das universidades, do próprio capitalismo. Martinho Lutero chamou a prensa móvel de “a mais alta graça de Deus”. Agora, mais uma vez, o gênio da tecnologia saiu da garrafa. Com a prensa móvel, ganhamos acesso à palavra escrita. Com a internet, cada um de nós pode ser seu próprio editor. A imprensa nos deu acesso ao conhecimento que já havia sido produzido e estava registrado. A internet nos dá acesso ao conhecimento contido no cérebro de outras pessoas em qualquer parte do mundo. Isso é uma revolução. E, tal como aconteceu no passado, está fazendo com que nossas instituições se tornem obsoletas. TAPSCOTT, D. Entrevista concedida a Augusto Nunes. Veja, 21 abr. 2011 (adaptado)."], "stem": "Segundo o pesquisador entrevistado, a internet revolucionou a história da mesma forma que a prensa móvel de Gutenberg revolucionou o mundo no século XV. De acordo com o texto, as duas invenções, de maneira similar, provocaram o(a)", "options": ["ocorrência de revoluções em busca por governos mais democráticos.", "divulgação do conhecimento produzido em papel nas diversas instituições.", "organização das sociedades a favor do acesso livre à educação e às universidades.", "comércio do conhecimento produzido e registrado em qualquer parte do mundo.", "democratização do conhecimento pela divulgação de ideias por meio de publicações."], "key": 4, "comment": "Segundo o entrevistado, prensa e internet ampliam a circulação de ideias e o acesso ao conhecimento. O paralelo central é a democratização do conhecimento, não a comercialização de arquivos ou o acesso exclusivamente a universidades.", "evidence": "A prensa dá acesso ao que já foi registrado; a internet permite circulação do conhecimento de outras pessoas.", "application": "Relacionar tecnologias da comunicação às formas sociais de produzir e compartilhar conhecimento. A resposta interpreta a posição do entrevistado.", "preserveLines": false, "figure": null, "figureAlt": "", "source": "ENEM 2017 PPL. Item 399 na numeração de “Dominando Linguagens”, p. 276. Gabarito conferido na seção de respostas do material enviado."}, {"id": "tipos-2018-cores", "origin": "ENEM", "year": 2018, "skill": 18, "pages": [1], "body": ["Cores do Brasil Ganhou nova versão, revista e ampliada, o livro lançado em 1988 pelo galerista Jacques Ardies, cuja proposta é ser publicação informativa sobre nomes do “movimento arte naïf do Brasil”, como define o autor. Trata-se de um caminho estético fundamental na arte brasileira, assegura Ardies. O termo em francês foi adotado por designar internacionalmente a produção que no Brasil é chamada de arte popular ou primitivismo, esclarece Ardies. O organizador do livro explica que a obra não tem a pretensão de ser um dicionário. “Falta muita gente. São muitos artistas”, observa. A nova edição veio da vontade de atualizar informações publicadas há 26 anos. Ela incluiu artistas em atividade atualmente e veteranos que ficaram de fora do primeiro livro. A arte naïf no Brasil traz 79 autores de várias regiões do Brasil. WALTER SEBASTIÃO. Estado de Minas, 17 jan. 2015 (adaptado)."], "stem": "O fragmento do texto jornalístico aborda o lançamento de um livro sobre arte naïf no Brasil. Na organização desse trecho predomina o uso da sequência", "options": ["injuntiva, sugerida pelo destaque dado à fala do organizador do livro.", "argumentativa, caracterizada pelo uso de adjetivos sobre o livro.", "narrativa, construída pelo uso de discurso direto e indireto.", "descritiva, formada com base em dados editoriais da obra.", "expositiva, composta por informações sobre a arte naïf."], "key": 4, "preserveLines": false, "figure": null, "figureAlt": "", "comment": "Predomina a exposição: o trecho apresenta e esclarece informações sobre a arte naïf, sua denominação e a proposta da publicação. Citações e avaliações pontuais não transformam o conjunto numa defesa de tese, e o texto não orienta uma ação do leitor.", "evidence": "O trecho explica como o movimento é denominado e apresenta o conteúdo e a atualização do livro.", "application": "H18: identificar a organização predominante do texto. A sequência expositiva informa e explica; o gênero jornalístico não deve ser confundido com o tipo textual.", "source": "ENEM 2018 PPL. Questão 1 de “Questões de tipos textuais”, p. 1. Resposta E conferida no gabarito do mesmo arquivo."}]};
